def format_reference(p):
    authors = p["authors"]
    if len(authors) == 1:
        a = authors[0]
    elif len(authors) == 2:
        a = "%s, & %s" % (authors[0], authors[1])
    else:
        a = ", ".join(authors[:-1]) + ", & " + authors[-1]
    venue = p["venue"].replace(DEMO_VENUE_SUFFIX, "")
    return "%s (%d). %s. %s. https://doi.org/%s" % (a, p["year"], p["title"], venue, p["doi"])


def build_document_text(spec):
    """Render a demo document spec into plain text with numbered citations and a reference list."""
    ref_numbers, refs = {}, []
    body_sentences = []
    for sentence, ref in spec["items"]:
        if ref is None:
            body_sentences.append(sentence)
            continue
        rkey = ref if isinstance(ref, str) else ref["raw"]
        if rkey not in ref_numbers:
            ref_numbers[rkey] = len(refs) + 1
            refs.append(format_reference(CORPUS_BY_KEY[ref]) if isinstance(ref, str) else ref["raw"])
        body_sentences.append(sentence[:-1] + " [%d]." % ref_numbers[rkey])
    paragraphs, chunk = [], []
    for i, s in enumerate(body_sentences):
        if not chunk:
            fill = spec.get("filler", FILLER)
            chunk.append(fill[(len(paragraphs)) % len(fill)])
        chunk.append(s)
        if len(chunk) >= 4:
            paragraphs.append(" ".join(chunk))
            chunk = []
    if chunk:
        paragraphs.append(" ".join(chunk))
    lines = [spec["title"], "", "Abstract", spec["abstract"], "", "1. Introduction and Evidence Review"]
    for para in paragraphs:
        lines += [para, ""]
    lines += ["2. Conclusion", "Careful evaluation of the underlying evidence is required before clinical adoption.", "", "References"]
    lines += ["[%d] %s" % (i + 1, r) for i, r in enumerate(refs)]
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
for _env in (os.path.join(BASE_DIR, ".env"), os.path.join(BASE_DIR, "..", ".env")):  # minimal .env loader
    if os.path.isfile(_env):
        for _line in open(_env):
            if "=" in _line and not _line.lstrip().startswith("#"):
                _k, _v = _line.strip().split("=", 1)
                os.environ.setdefault(_k.strip(), _v.strip().strip('"'))
DATABASE_URL = os.getenv("DATABASE_URL", "sqlite:///" + os.path.join(BASE_DIR, "citeverify.db"))
SECRET_KEY = os.getenv("SECRET_KEY", "citeverify-dev-secret-change-me")
LIVE_LOOKUP = os.getenv("LIVE_LOOKUP", "true").lower() == "true"
ANTHROPIC_MODEL = os.getenv("ANTHROPIC_MODEL", "claude-opus-5-5")
CONTACT_EMAIL = os.getenv("CONTACT_EMAIL", "")  # optional: polite-pool email for Crossref/OpenAlex
MAX_UPLOAD_MB = 15
OUTDATED_YEARS = 10
CURRENT_YEAR = datetime.utcnow().year

VERDICTS = ["SUPPORTED", "PARTIALLY SUPPORTED", "UNSUPPORTED", "CONTRADICTORY", "POTENTIALLY OUTDATED", "NEEDS HUMAN REVIEW"]

# ---------------------------------------------------------------------------
# Database
# ---------------------------------------------------------------------------
engine = create_engine(DATABASE_URL, connect_args={"check_same_thread": False} if DATABASE_URL.startswith("sqlite") else {})
SessionLocal = sessionmaker(bind=engine, autoflush=False, expire_on_commit=False)
Base = declarative_base()
_db_lock = threading.Lock()


class User(Base):
    __tablename__ = "users"
    id = Column(Integer, primary_key=True)
    email = Column(String, unique=True, index=True)
    name = Column(String)
    role = Column(String)  # student | professor
    pw_hash = Column(String)
    program = Column(String, default="")
    created_at = Column(DateTime, default=datetime.utcnow)


class Document(Base):
    __tablename__ = "documents"
    id = Column(Integer, primary_key=True)
    owner_id = Column(Integer, ForeignKey("users.id"), index=True)
    title = Column(String)
    filename = Column(String)
    filetype = Column(String)
    size = Column(Integer, default=0)
    text = Column(Text, default="")
    version = Column(Integer, default=1)
    root_id = Column(Integer, nullable=True)  # id of the original version
    prev_id = Column(Integer, nullable=True)
    status = Column(String, default="processing")  # processing|analyzed|failed|submitted|in_review|reviewed|revision_requested
    stage = Column(Integer, default=0)
    error = Column(Text, default="")
    demo = Column(Boolean, default=False)
    summary = Column(Text, default="{}")
    created_at = Column(DateTime, default=datetime.utcnow)
    submitted_at = Column(DateTime, nullable=True)
    reviewed_at = Column(DateTime, nullable=True)


class Paper(Base):
    __tablename__ = "papers"
    id = Column(Integer, primary_key=True)
    key = Column(String, unique=True, index=True)  # demo key or doi
    title = Column(Text)
    authors = Column(Text, default="[]")
    year = Column(Integer, nullable=True)
    venue = Column(String, default="")
    doi = Column(String, default="", index=True)
    url = Column(String, default="")
    abstract = Column(Text, default="")
    sections = Column(Text, default="[]")
    cites = Column(Text, default="[]")
    source = Column(String, default="demo")
    simulated = Column(Boolean, default=False)


class Reference(Base):
    __tablename__ = "references"
    id = Column(Integer, primary_key=True)
    doc_id = Column(Integer, ForeignKey("documents.id"), index=True)
    idx = Column(Integer)
    label = Column(String)
    raw = Column(Text)
    title = Column(Text, default="")
    authors = Column(Text, default="")
    year = Column(Integer, nullable=True)
    doi = Column(String, default="")
    venue = Column(String, default="")
    paper_id = Column(Integer, nullable=True)
    meta_status = Column(String, default="unverified")  # verified|mismatch|unverified|not_found
    issues = Column(Text, default="[]")


class Claim(Base):
    __tablename__ = "claims"
    id = Column(Integer, primary_key=True)
    doc_id = Column(Integer, ForeignKey("documents.id"), index=True)
    idx = Column(Integer)
    text = Column(Text)
    citation_labels = Column(Text, default="[]")
    ref_id = Column(Integer, nullable=True)
    paper_id = Column(Integer, nullable=True)
    verdict = Column(String)
    confidence = Column(Float, default=0.0)
    explanation = Column(Text, default="")
    evidence = Column(Text, default="[]")
    numeric = Column(Text, default="[]")
    mismatch = Column(Text, default="{}")
    outdated = Column(Text, default="{}")
    chain = Column(Text, default="{}")
    engine = Column(String, default="rules")
    review_status = Column(String, default="pending")  # pending|confirmed|overridden|flagged
    prof_verdict = Column(String, default="")
    prof_note = Column(Text, default="")
    replacement = Column(Text, default="{}")


class Feedback(Base):
    __tablename__ = "feedback"
