def jl(s, default=None):
    try:
        return json.loads(s) if s else (default if default is not None else None)
    except Exception:
        return default


def jd(o):
    return json.dumps(o, ensure_ascii=False)


# ---------------------------------------------------------------------------
# Auth (HMAC-signed tokens, PBKDF2 passwords)
# ---------------------------------------------------------------------------
def hash_pw(pw: str) -> str:
    salt = os.urandom(12)
    return base64.b64encode(salt).decode() + "$" + hashlib.pbkdf2_hmac("sha256", pw.encode(), salt, 60000).hex()


def check_pw(pw: str, stored: str) -> bool:
    try:
        salt_b64, digest = stored.split("$")
        return hmac.compare_digest(hashlib.pbkdf2_hmac("sha256", pw.encode(), base64.b64decode(salt_b64), 60000).hex(), digest)
    except Exception:
        return False


def make_token(user: User) -> str:
    payload = "%d:%s:%d" % (user.id, user.role, int(time.time()) + 7 * 86400)
    sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return base64.urlsafe_b64encode((payload + ":" + sig).encode()).decode()


def read_token(token: str) -> Optional[Tuple[int, str]]:
    try:
        uid, role, exp, sig = base64.urlsafe_b64decode(token.encode()).decode().split(":")
        payload = "%s:%s:%s" % (uid, role, exp)
        if not hmac.compare_digest(sig, hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()):
            return None
        if int(exp) < time.time():
            return None
        return int(uid), role
    except Exception:
        return None


def current_user(authorization: str = Header(default="")) -> User:
    token = authorization.replace("Bearer ", "").strip()
    parsed = read_token(token) if token else None
    if not parsed:
        raise HTTPException(401, "Not authenticated")
    db = SessionLocal()
    try:
        user = db.get(User, parsed[0])
    finally:
        db.close()
    if not user or user.role != parsed[1]:
        raise HTTPException(401, "Invalid session")
    return user


def require_student(user: User = Depends(current_user)) -> User:
    if user.role != "student":
        raise HTTPException(403, "Student portal only")
    return user


def require_professor(user: User = Depends(current_user)) -> User:
    if user.role != "professor":
        raise HTTPException(403, "Professor portal only")
    return user


# ---------------------------------------------------------------------------
# Text utilities
# ---------------------------------------------------------------------------
STOP = set("""a an the of in on at to for from by with and or but is are was were be been being this that these those it its as
into than then there their them they we our you your he she his her not no nor so such can could may might will would should shall
has have had do does did also more most less least very much many some any each other between within without across over under
about after before during while which who whom whose what when where why how all every both either neither one two three four five
six seven eight nine ten per via up down out new now just only""".split())
GENERIC = set("""according recent review study studies show shown showed research paper papers report reported reports evidence found
finding findings result results suggest suggests using used use based system systems time level levels data approach method methods
model models proposed work article literature author authors significant significantly""".split())
SYN = {"x-ray": "radiograph", "x-rays": "radiograph", "physicians": "clinician", "physician": "clinician", "doctors": "clinician",
       "doctor": "clinician", "ehr": "record", "ml": "machine", "smartwatches": "smartwatch", "wearables": "wearable"}
NEG_RE = re.compile(r"\b(not|no|never|cannot|can't|don't|doesn't|didn't|failed to|fails to|neither|nor|without evidence|contrary to|"
                    r"did not|does not|do not|is not|are not|was not|were not|no significant|unable to)\b", re.I)
LIMIT_RE = re.compile(r"(may not generali[sz]e|small sample|single[- ]cent|limited to|should not be interpreted|limitation|"
                      r"may underestimate|may overestimate|caution|preliminary|pilot study|may have contributed|smaller on)", re.I)
ABSOLUTE_RE = re.compile(r"\b(all|always|every|never|eliminat\w*|guarantee\w*|universally|consistently|completely|entirely|"
                         r"any|proves?|definitively|without exception)\b", re.I)
NUM_RE = re.compile(r"(?<![\w.])(\d{1,3}(?:,\d{3})+|\d+(?:\.\d+)?)\s*(%|percent|percentage points?|pp\b)?", re.I)
DOI_RE = re.compile(r"10\.\d{4,9}/[^\s\"<>]+", re.I)
SCALE_WORDS = {"thousand": 1e3, "million": 1e6, "billion": 1e9, "trillion": 1e12}
WORD_NUMS = {w: i + 2 for i, w in enumerate("two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen "
                                              "sixteen seventeen eighteen nineteen twenty".split())}
WORD_NUMS.update({"thirty": 30, "forty": 40, "fifty": 50, "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90, "dozen": 12})
WORD_NUM_RE = re.compile(r"(?<![\w-])(%s)(?![\w])(?!\s+(?:hundred|thousand|million|billion))" % "|".join(WORD_NUMS), re.I)
CITE_NUM_RE = re.compile(r"\[(\d+(?:\s*[-–,]\s*\d+)*)\]")
CITE_AY_RE = re.compile(r"\(([A-Z][a-z][A-Za-z'\-]+)(?: et al\.?| (?:and|&) [A-Z][A-Za-z'\-]+)?,? (\d{4})[a-z]?(?:;[^)]*)?\)")
CITE_NARR_RE = re.compile(r"\b([A-Z][a-z][A-Za-z'\-]+)(?: et al\.?| (?:and|&) [A-Z][A-Za-z'\-]+)? \((\d{4})[a-z]?\)")
INLINE_CORPUS_RE = re.compile(r"\[\[(P\d+)\]\]")
METRIC_WORDS = ["accuracy", "sensitivity", "specificity", "precision", "recall", "f1", "auc", "reduction", "increase", "improv",
                "participants", "patients", "sample", "readmission", "waiting", "trust", "error", "rate", "score", "value"]


def stem(w: str) -> str:
    w = SYN.get(w, w)
    if 4 <= len(w) <= 5 and w.endswith("s") and w[-2] not in "suie":
        return w[:-1]                       # short plurals and acronyms: gpus, ecgs, cnns, days
    for suf in ("ations", "ation", "tions", "tion", "ions", "ion", "ings", "ing", "ies", "ied", "ers", "ed", "es", "s", "ly", "e"):
        if w.endswith(suf) and len(w) - len(suf) >= 4:
            w = w[: -len(suf)]
            break
    return w[:5]


def tokens(text: str) -> set:
    text = INLINE_CORPUS_RE.sub(" ", CITE_NUM_RE.sub(" ", text.lower()))
    out = set()
    for raw in re.findall(r"[a-z][a-z\-']*", text):
        for w in raw.split("-"):
            w = w.strip("'")
            if len(w) < 2 or w in STOP or w in GENERIC:
                continue
            out.add(stem(SYN.get(w, w)))
    return out


def overlap(claim_tokens: set, text: str) -> float:
    if not claim_tokens:
        return 0.0
    return len(claim_tokens & tokens(text)) / float(len(claim_tokens))


def split_sentences(text: str) -> List[str]:
    t = re.sub(r"\s+", " ", text.replace("et al.", "et al§").replace("e.g.", "e§g§").replace("i.e.", "i§e§"))
    parts = re.split(r"(?<=[.!?])\s+(?=[A-Z\[(\"“])", t)
    return [p.replace("§", ".").strip() for p in parts if p.strip()]


def parse_numbers(text: str) -> List[Dict[str, Any]]:
    clean = INLINE_CORPUS_RE.sub("", CITE_NUM_RE.sub("", text))
    out = []
    for m in NUM_RE.finditer(clean):
        raw, unit = m.group(1), (m.group(2) or "").lower()
        val = float(raw.replace(",", ""))
        if not unit and 1900 <= val <= 2100 and "." not in raw:
            continue  # a year, not a measurement
        kind = "percent" if unit in ("%", "percent") else ("pp" if unit.startswith("percentage") or unit == "pp" else "number")
        raw_txt = m.group(0).strip()
        if not unit:
            suf = re.match(r"\s?([KkMB])\b", clean[m.end():m.end() + 3])
            word = re.match(r"\s?(thousand|million|billion|trillion)\b", clean[m.end():m.end() + 10], re.I)
            if suf:
                val *= {"k": 1e3, "m": 1e6, "b": 1e9}[suf.group(1).lower()]
                raw_txt += suf.group(1)
            elif word:
                val *= SCALE_WORDS[word.group(1).lower()]
                raw_txt += " " + word.group(1)
        ctx = tokens(" ".join(clean[:m.start()].split()[-4:] + clean[m.end():].split()[:4]))
        out.append({"value": val, "raw": raw_txt, "kind": kind, "pos": m.start(), "ctx": ctx})
    for m in WORD_NUM_RE.finditer(clean):                    # "six countries", "eight GPUs"
        ctx = tokens(" ".join(clean[:m.start()].split()[-4:] + clean[m.end():].split()[:4]))
        out.append({"value": float(WORD_NUMS[m.group(1).lower()]), "raw": m.group(1), "kind": "number", "pos": m.start(), "ctx": ctx, "word": True})
    out.sort(key=lambda n: n["pos"])
    return out


def sim_title(a: str, b: str) -> float:
    ta, tb = tokens(a or ""), tokens(b or "")
    if not ta or not tb:
        return 0.0
    return len(ta & tb) / float(len(ta | tb))


_TAG_RE = re.compile(r"""</?[A-Za-z][\w:.-]*(?:\s+[\w:.-]+\s*=\s*(?:"[^"]*"|'[^']*'))*\s*/?>""")   # only real markup: <jats:p>, </i>, <sub> - never "P<0.001"


def clean_text(s: str) -> str:
    """Strip JATS/HTML markup from registry abstracts. A bare '<' is data ('P<0.001', '<5% error'), not a tag."""
    return re.sub(r"\s+", " ", html.unescape(_TAG_RE.sub(" ", s or ""))).strip()


# ---------------------------------------------------------------------------
# Document extraction
# ---------------------------------------------------------------------------
def extract_text(filename: str, data: bytes) -> str:
    name = filename.lower()
    if name.endswith(".pdf"):
        import fitz  # PyMuPDF
        with fitz.open(stream=data, filetype="pdf") as pdf:
            return "\n".join(page.get_text() for page in pdf)
    if name.endswith(".docx"):
        import docx
        d = docx.Document(io.BytesIO(data))
        return "\n".join(p.text for p in d.paragraphs)
    if name.endswith(".txt"):
        return data.decode("utf-8", errors="ignore")
    raise HTTPException(400, "Unsupported file type. Please upload a PDF or DOCX file.")


REF_STOP_RE = re.compile(r"^\s*(appendix|appendices|supplementary|supporting information|acknowledg|attention visuali[sz]ations|author contributions|figure captions)\b", re.I)


def _join_ref_lines(prev: str, nxt: str) -> str:
    """Join wrapped reference lines, repairing hyphenated words and DOIs/URLs broken across lines."""
    if prev.endswith("-"):
        last_tok = prev.split()[-1] if prev.split() else ""
        if "/" in last_tok or "doi" in last_tok.lower() or re.search(r"\d-$", last_tok):
            return prev + nxt                      # DOI / URL / number range: keep the hyphen, no space
        if re.match(r"[a-z]", nxt):
            return prev[:-1] + nxt                 # "esti-" + "mating" -> "estimating"
        return prev + nxt
    if re.search(r"(https?://\S*|doi\.org/\S*)$", prev) and not re.match(r"[A-Z]", nxt):
        return prev + nxt                          # URL wrapped mid-way
    return prev + " " + nxt


def split_body_references(text: str) -> Tuple[str, List[str]]:
    lines = [l.rstrip() for l in text.splitlines()]
    ref_idx = None
    for i, l in enumerate(lines):
        if re.match(r"^\s*(\d+\.?\s*)?(references|bibliography|works cited|reference list|literature cited)\s*:?\s*$", l, re.I):
            ref_idx = i
    if ref_idx is None:
        return text, []
    body = "\n".join(lines[:ref_idx])
    ref_lines = []
    for l in lines[ref_idx + 1:]:
        l = l.strip()
        if REF_STOP_RE.match(l):
            break                                    # appendix after the bibliography
        ref_lines.append(l)
    entries: List[str] = []
    num_inline = re.compile(r"^\[?(\d{1,3})[\].]\s+\S")
    num_alone = re.compile(r"^\[?(\d{1,3})[\].]$")
    numbered = sum(1 for l in ref_lines if num_inline.match(l) or num_alone.match(l)) >= 2
    expected = 1
    for l in ref_lines:
        if not l:
            continue
        if numbered:
            m = num_inline.match(l) or num_alone.match(l)
            if m and int(m.group(1)) in (expected, expected + 1):   # only accept the next number in sequence (years are not entry numbers)
                expected = int(m.group(1)) + 1
                entries.append(l)
                continue
            if re.fullmatch(r"\d{1,4}", l):
                continue                                             # page number between columns
            if entries:
                entries[-1] = (entries[-1] + " " + l) if num_alone.match(entries[-1]) else _join_ref_lines(entries[-1], l)
        else:
            if re.match(r"^[A-Z][A-Za-z'\-]+,\s+[A-Z]", l) or not entries:   # APA: new entry starts with "Surname, X."
                entries.append(l)
            else:
                entries[-1] = _join_ref_lines(entries[-1], l)
    return body, [e[:1500] for e in entries]


ARXIV_RE = re.compile(r"(?:arxiv[:\s]*|abs/|arxiv\.org/(?:abs|pdf)/)(\d{4}\.\d{4,5})", re.I)
_INITIALS_END = re.compile(r"(?:^|[\s,(])(?:(?:[A-Z]\.?){1,3}|[A-Z]\.?-[A-Z])$")


def _ref_segments(text: str) -> List[str]:
    """Split a reference into '. '-separated segments without breaking on author initials ('Y. Koren', 'L.-J. Li')."""
    pieces = [p for p in re.split(r"\.\s+", text) if p.strip()]
    segs: List[str] = []
    for p in pieces:
        if segs and ((_INITIALS_END.search(segs[-1]) and re.match(r"^[A-Z][^\s,.]*(?:,|\s+and\b|$)", p)) or re.match(r"^et al\b", p)):
            segs[-1] += ". " + p                     # "R.M. Bell and Y" + "Koren" / "+ et al" -> same author segment
        else:
            segs.append(p.strip())
    return segs


def parse_reference(raw: str, idx: int) -> Dict[str, Any]:
    label = str(idx)
    m = re.match(r"^\[?(\d+)[\].]\s*(.*)$", raw)
    text = raw
    if m:
        label, text = m.group(1), m.group(2)
    text = text.replace("ﬁ", "fi").replace("ﬂ", "fl")
    doi_m = DOI_RE.search(text)
    doi = doi_m.group(0).rstrip(".,;)").lower() if doi_m else ""
    arxiv_m = ARXIV_RE.search(text)
    year, authors, title, venue = None, "", "", ""
    ym = re.search(r"\((\d{4})[a-z]?\)", text) or re.search(r"\b(19\d{2}|20\d{2})\b", text)
    if ym:
        year = int(ym.group(1))
    q = re.search(r"[\"“](.+?)[,.]?[\"”]", text)
    clean = re.sub(r"https?://\S+", "", text)
    segs = _ref_segments(clean)
    if q:  # IEEE style: A. Author, "Title," Venue, year.
        title = q.group(1).strip()
        authors = text[: q.start()].strip(" ,")
        venue = text[q.end():].split(",")[0].strip(" ,.")
    elif len(segs) >= 2 and re.match(r"^\(\d{4}[a-z]?\)", segs[1]):          # APA: Authors. (Year). Title. Venue.
        authors = segs[0]
        after = re.sub(r"^\(\d{4}[a-z]?\)\.?\s*", "", segs[1]).strip()
        title = after or (segs[2] if len(segs) > 2 else "")
        rest = segs[2:] if not after else segs[2:]
        venue = rest[1] if not after and len(rest) > 1 else (rest[0] if rest else "")
    elif segs:                                                                  # NeurIPS / Vancouver: Authors. Title. Venue, year.
        authors = segs[0]
        title = segs[1] if len(segs) > 1 else ""
        venue = segs[2] if len(segs) > 2 else ""
    title = re.sub(r"^et al\.?\s*", "", title)
    title = re.split(r",\s*\(\d{4}[a-z]?\)", title)[0]          # "Title, (2021), In Book..." -> "Title"
    title = re.sub(r"\s*\(\d{4}[a-z]?\)\s*$", "", title)
    first_author = re.split(r",|&| and ", authors)[0].strip() if authors else ""
    return {"label": label, "raw": raw, "doi": doi, "arxiv": arxiv_m.group(1) if arxiv_m else "", "year": year, "authors": authors,
            "first_author": first_author, "title": title.strip(" ."), "venue": re.sub(r"https?://\S+", "", venue).strip(" .,")}


GENERAL_CLAIM_RE = re.compile(r"\b(worldwide|globally|nationally|world|most|majority|nearly|approximately|about|over|more than|up to|"
                              r"estimated|studies|research(?:ers)?|reports?|surveys?|according|population|people|patients|hospitals|"
                              r"countries|students|users|companies|annually|every year|per year|prevalence|rate of)\b", re.I)
TECHNICAL_RE = re.compile(r"(=|\b(layers?|parameters?|neurons?|epochs?|steps?|batch(?:es)?|learning rate|dimension\w*|kernels?|pixels?|"
                          r"gpus?|training|trained|validation|test set|dataset|hyper-?parameters?|figure|fig\.?|table|equation|"
                          r"accuracy of (?:the|our) model|network|test error|error rates?|top-[0-9])\b)", re.I)
DATASET_RE = re.compile(r"\b(datasets?|data sets?|database|corpus|benchmark|workbench|toolkit|software|library|repository|"
                        r"package|ncbi|geo|uci|kaggle)\b", re.I)
OWN_WORK_RE = re.compile(r"\b(we|our|ours|us|this paper|this work|this study|this article|the present study|in this section|"
                         r"(?:this|the proposed|the present) (?:scheme|method|approach|model|network|architecture|technique|system|framework))\b", re.I)
CAPTION_RE = re.compile(r"^\s*(fig\.?|figure|table|tab\.|algorithm|equation|eq\.)\s*\d", re.I)


def extract_claims(body: str) -> List[Dict[str, Any]]:
    claims = []
    paragraphs = [p for p in re.split(r"\n\s*\n|\n(?=[A-Z0-9])", body) if p.strip()]
    for para in paragraphs:
        flat = para.replace("\n", " ").strip()
        if len(flat.split()) < 8:  # headings, titles
            continue
        for sent in split_sentences(flat):
            words = sent.split()
            if len(words) < 6:
                continue
            labels = []
            for m in CITE_NUM_RE.finditer(sent):
                for part in re.split(r"\s*,\s*", m.group(1)):
                    if re.search(r"[-–]", part):
                        a, b = [int(x) for x in re.split(r"\s*[-–]\s*", part)]
                        labels += [str(i) for i in range(a, min(b, a + 30) + 1)]
                    else:
                        labels.append(part.strip())
            for m in list(CITE_AY_RE.finditer(sent)) + list(CITE_NARR_RE.finditer(sent)):
                labels.append("%s %s" % (m.group(1), m.group(2)))
            labels = list(dict.fromkeys(labels))
            if labels and (OWN_WORK_RE.search(sent) or re.search(r"\b(dataset|data set)\s*\d", sent, re.I)) and all(
                    DATASET_RE.search(" ".join(citation_window(sent, l).split()[:8])) for l in labels):
                continue      # the citation only identifies a dataset / tool used in the authors' own experiment
            if not labels:
                # Uncited sentences are only claims if they assert an external statistic. The authors' own results
                # ("we achieved 37.5% error") and figure/table captions are not claims that need a citation.
                if OWN_WORK_RE.search(sent) or CAPTION_RE.match(sent):
                    continue
                has_stat = bool([n for n in parse_numbers(sent) if n["kind"] != "number" or n["value"] > 10])
                if not (has_stat and re.search(r"\b(is|are|was|were|reduce|increase|achieve|improve|use|show|reach|detect)\w*", sent, re.I)):
                    continue
                if TECHNICAL_RE.search(sent) or not GENERAL_CLAIM_RE.search(sent):
                    continue          # technical description of the work itself, not a factual claim about the world
            claims.append({"text": sent.strip(), "labels": labels})
    return claims


# ---------------------------------------------------------------------------
# Paper retrieval (demo corpus first, then live scholarly APIs)
# ---------------------------------------------------------------------------
HTTP_HEADERS = {"User-Agent": "CiteVerify/1.0 (hackathon research prototype%s)" % ("; mailto:" + CONTACT_EMAIL if CONTACT_EMAIL else "")}


_HOST_MIN_INTERVAL = {"export.arxiv.org": 3.1, "api.semanticscholar.org": 1.1, "api.crossref.org": 0.25,
                      "api.crossref.org#search": 0.4 if os.getenv("CONTACT_EMAIL") else 1.05, "api.openalex.org": 0.2,
                      "doi.org": 0.2, "www.ebi.ac.uk": 0.15}
_SERIAL_HOSTS = {"api.crossref.org", "api.crossref.org#search"}   # Crossref's public pool allows one concurrent request
_host_locks: Dict[str, threading.Lock] = {}
_host_last: Dict[str, float] = {}
_host_blocked_until: Dict[str, float] = {}
_host_meta_lock = threading.Lock()


def _pace(host: str):
    with _host_meta_lock:
        lock = _host_locks.setdefault(host, threading.Lock())
    with lock:
        wait = _host_last.get(host, 0) + _HOST_MIN_INTERVAL.get(host, 0) - time.time()
        if wait > 0:
            time.sleep(wait)
        _host_last[host] = time.time()


S2_API_KEY = os.getenv("SEMANTIC_SCHOLAR_API_KEY", "")


OPENALEX_API_KEY = os.getenv("OPENALEX_API_KEY", "")


def http_get(url: str, params: Optional[dict] = None, timeout: float = 12.0, retries: int = 2, raw: bool = False,
             extra_headers: Optional[dict] = None) -> Tuple[int, Any]:
    """Polite GET: per-host pacing, retries with back-off on 429/5xx, and a short circuit breaker for rate-limited hosts.
    Returns (status, json-or-text). status 0 means the service could not be reached."""
    host = re.sub(r"^https?://([^/]+).*$", r"\1", url)
    if _host_blocked_until.get(host, 0) > time.time():
        return 429, None
    params = dict(params or {})
    if host == "api.crossref.org":
        if CONTACT_EMAIL:
            params.setdefault("mailto", CONTACT_EMAIL)           # Crossref "polite pool"
        if "query.bibliographic" in params or "filter" in params:
            host = "api.crossref.org#search"                    # Crossref search: 1 req/s public, 3 req/s polite (2026 limits)
    if "openalex.org" in host and OPENALEX_API_KEY:
        params.setdefault("api_key", OPENALEX_API_KEY)
    status = 0
    headers = dict(HTTP_HEADERS, **({"x-api-key": S2_API_KEY} if S2_API_KEY and "semanticscholar" in host else {}), **(extra_headers or {}))
    serial = host in _SERIAL_HOSTS
    if serial:
        retries = max(retries, 4)
    for attempt in range(retries + 1):
        _pace(host)
        wait = 0.8 * (attempt + 1)
        try:
            if serial:
                with _host_locks[host]:
                    r = httpx.get(url, params=params or None, headers=headers, timeout=timeout, follow_redirects=True)
            else:
                r = httpx.get(url, params=params or None, headers=headers, timeout=timeout, follow_redirects=True)
            status = r.status_code
            if status == 200:
                return 200, (r.text if raw else r.json())
            if status in (400, 404):
                return status, None
            if status == 429:
                try:
                    wait = max(float(r.headers.get("retry-after", "0")), 2.5 * (attempt + 1))
                except ValueError:
                    wait = 2.5 * (attempt + 1)
        except Exception:
            status = 0
        time.sleep(min(wait, 15))
    if status == 429 and not serial:
        _host_blocked_until[host] = time.time() + 30      # stop hammering a rate-limited optional service for a while
    return status, None


def http_json(url: str, params: Optional[dict] = None, timeout: float = 12.0) -> Optional[dict]:
    return http_get(url, params, timeout, retries=1)[1]


def paper_to_dict(p: Paper) -> Dict[str, Any]:
    return {"id": p.id, "key": p.key, "title": p.title, "authors": jl(p.authors, []), "year": p.year, "venue": p.venue,
            "doi": p.doi, "url": p.url or ("https://doi.org/" + p.doi if p.doi and not p.simulated else ""),
            "abstract": p.abstract, "sections": jl(p.sections, []), "cites": jl(p.cites, []), "source": p.source,
            "simulated": p.simulated}


def get_or_create_paper(db, data: Dict[str, Any]) -> Paper:
    with _db_lock:
        p = db.query(Paper).filter(Paper.key == data["key"]).first()
        if p:
            return p
        p = Paper(key=data["key"], title=data.get("title", ""), authors=jd(data.get("authors", [])), year=data.get("year"),
                  venue=data.get("venue", ""), doi=data.get("doi", ""), url=data.get("url", ""), abstract=data.get("abstract", ""),
                  sections=jd(data.get("sections", [])), cites=jd(data.get("cites", [])), source=data.get("source", "demo"),
                  simulated=data.get("simulated", False))
        db.add(p)
        db.commit()
        return p


def crossref_to_paper(item: dict) -> Dict[str, Any]:
    authors = ["%s, %s" % (a.get("family", ""), (a.get("given", "") or "")[:1] + ".") for a in item.get("author", []) if a.get("family")]
    year = None
    for k in ("published-print", "published-online", "issued", "created"):
        parts = (item.get(k) or {}).get("date-parts") or [[None]]
        if parts and parts[0] and parts[0][0]:
            year = parts[0][0]
            break
    doi = (item.get("DOI") or "").lower()
    return {"key": doi, "title": clean_text((item.get("title") or [""])[0]), "authors": authors, "year": year,
            "venue": clean_text((item.get("container-title") or [""])[0]), "doi": doi, "url": "https://doi.org/" + doi,
            "abstract": clean_text(item.get("abstract", "")).replace("Abstract ", "", 1), "sections": [], "cites": [],
            "source": "crossref", "simulated": False}


def arxiv_query(params: dict) -> List[Dict[str, Any]]:
    """Query the arXiv API (Atom XML) and return simplified entries."""
    import xml.etree.ElementTree as ET
    status, text = http_get("https://export.arxiv.org/api/query", params, timeout=20, raw=True)
    if status != 200 or not text:
        return []
    ns = {"a": "http://www.w3.org/2005/Atom", "x": "http://arxiv.org/schemas/atom"}
    out = []
    try:
        root = ET.fromstring(text)
    except Exception:
        return []
    for e in root.findall("a:entry", ns):
        aid = (e.findtext("a:id", "", ns) or "").rsplit("/abs/", 1)[-1]
        title = re.sub(r"\s+", " ", e.findtext("a:title", "", ns) or "").strip()
        if not title or title.lower() == "error":
            continue
        summary = re.sub(r"\s+", " ", e.findtext("a:summary", "", ns) or "").strip()
        published = e.findtext("a:published", "", ns) or ""
        names = [re.sub(r"\s+", " ", a.findtext("a:name", "", ns) or "") for a in e.findall("a:author", ns)]
        authors = ["%s, %s." % (n.split()[-1], n.split()[0][:1]) for n in names if n.split()]
        doi = (e.findtext("x:doi", "", ns) or "").lower()
        base = re.sub(r"v\d+$", "", aid)
        out.append({"key": "arxiv:" + base, "title": title, "authors": authors, "year": int(published[:4]) if published[:4].isdigit() else None,
                    "venue": "arXiv", "doi": doi, "url": "https://arxiv.org/abs/" + base, "abstract": summary, "sections": [], "cites": [],
                    "source": "arxiv", "simulated": False, "arxiv_id": base})
    return out


def arxiv_batch(ids: List[str]) -> Dict[str, Dict[str, Any]]:
    out: Dict[str, Dict[str, Any]] = {}
    ids = list(dict.fromkeys(i for i in ids if i))
    for k in range(0, len(ids), 40):
        chunk = ids[k:k + 40]
        entries = arxiv_query({"id_list": ",".join(chunk), "max_results": 40})
        if not entries:                                   # arXiv throttles bursts: wait once and retry
            time.sleep(5)
            _host_blocked_until.pop("export.arxiv.org", None)
            entries = arxiv_query({"id_list": ",".join(chunk), "max_results": 40})
        for e in entries:
            out[e["arxiv_id"]] = e
    return out


def strip_accents(text: str) -> str:
    import unicodedata
    text = re.sub("[\u00b8\u00a8\u00b4\u02c6\u02dc\u02da`]", "", text or "")       # spacing diacritics from PDF extraction
    return unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode()


def _norm_tokens(text: str) -> set:
    return tokens(strip_accents(text))


def match_score(ref: Dict[str, Any], cand_title: str, cand_year: Optional[int], cand_authors: List[str]) -> float:
    """How well a candidate record matches the cited reference (0..1). Uses the full reference text, so it works
    even when the reference's title could not be parsed cleanly."""
    ct = _norm_tokens(cand_title)
    if len(ct) < 1:
        return 0.0
    rt = _norm_tokens(ref.get("raw", ""))
    contain = len(ct & rt) / float(len(ct))
    year_ok = bool(ref.get("year") and cand_year and abs(int(ref["year"]) - int(cand_year)) <= 1)
    surnames = {re.sub(r"[^a-z]", "", strip_accents(a.split(",")[0]).lower()) for a in cand_authors if a}
    raw_low = re.sub(r"[^a-z ]", " ", strip_accents(ref.get("raw", "")).lower())
    author_ok = any(sn and len(sn) > 1 and re.search(r"\b%s\b" % re.escape(sn), raw_low) for sn in surnames)
    if contain < 0.8:
        return 0.0
    if ref.get("year") and cand_year and abs(int(ref["year"]) - int(cand_year)) > 1:
        return 0.0                                  # a search hit from a different year is a different work
    if len(ct) <= 2 and not (year_ok and author_ok):
        return 0.0                                  # very short titles need both author and year to agree
    rt_title = _norm_tokens(ref.get("title", ""))
    if len(rt_title) >= 3 and len(ct & rt_title) / float(len(rt_title)) < 0.6:
        return 0.0                                  # "Boltzmann Machines" is not "Rectified linear units improve ... Boltzmann machines"
    return round(contain * 0.6 + (0.2 if year_ok else 0) + (0.2 if author_ok else 0), 3)


def europe_pmc_abstract(doi: str) -> str:
    res = http_json("https://www.ebi.ac.uk/europepmc/webservices/rest/search",
                    {"query": 'DOI:"%s"' % doi, "resultType": "core", "format": "json", "pageSize": 1})
    for item in ((res or {}).get("resultList") or {}).get("result", [])[:1]:
        if (item.get("doi") or "").lower() == doi.lower() and item.get("abstractText"):
            return clean_text(item["abstractText"])
    return ""


def doi_csl(doi: str) -> Tuple[int, Optional[dict]]:
    """Ask doi.org itself (content negotiation). Works for every registration agency: Crossref, DataCite (arXiv, Zenodo,
    datasets, software), mEDRA, ... A 404 here means the DOI is not registered anywhere."""
    return http_get("https://doi.org/" + doi, extra_headers={"Accept": "application/vnd.citationstyles.csl+json"}, retries=1)


def csl_to_paper(csl: dict, doi: str) -> Dict[str, Any]:
    authors = ["%s, %s" % (a.get("family", ""), (a.get("given", "") or "")[:1] + ".") for a in csl.get("author", []) if a.get("family")]
    parts = ((csl.get("issued") or {}).get("date-parts") or [[None]])[0]
    title = csl.get("title") or ""
    return {"key": doi.lower(), "title": clean_text(title if isinstance(title, str) else (title or [""])[0]), "authors": authors,
            "year": parts[0] if parts else None, "venue": clean_text(csl.get("container-title") or csl.get("publisher") or ""),
            "doi": doi.lower(), "url": "https://doi.org/" + doi, "abstract": clean_text(csl.get("abstract", "")), "sections": [],
            "cites": [], "source": "doi.org", "simulated": False}


def fetch_abstract(doi: str, title: str = "") -> Tuple[str, str]:
    if doi:
        epmc = europe_pmc_abstract(doi)
        if epmc:
            return epmc, "europepmc"
        s2 = http_json("https://api.semanticscholar.org/graph/v1/paper/DOI:%s" % doi, {"fields": "abstract"}, timeout=8)
        if s2 and s2.get("abstract"):
            return s2["abstract"], "semanticscholar"
        oa = http_json("https://api.openalex.org/works/doi:%s" % doi, timeout=8)
        if oa and oa.get("abstract_inverted_index"):
            inv = oa["abstract_inverted_index"]
            words = sorted(((pos, w) for w, ps in inv.items() for pos in ps))
            return " ".join(w for _, w in words), "openalex"
    if title and len(title.split()) >= 3:              # many CS papers have an arXiv version with an abstract
        for e in arxiv_query({"search_query": 'ti:"%s"' % re.sub(r'["]', "", title)[:200], "max_results": 3}):
            if sim_title(e["title"], title) >= 0.8:
                return e["abstract"], "arxiv"
    return "", ""


def live_lookup_reference(ref: Dict[str, Any], arxiv: Optional[Dict[str, Dict[str, Any]]] = None) -> Tuple[Optional[Dict[str, Any]], str]:
    """Locate the cited paper. Order: DOI -> arXiv id -> Crossref bibliographic match on the full reference ->
    Semantic Scholar title match -> arXiv title search. Every candidate must agree with the reference text."""
    # 0. arXiv DOIs (10.48550/arXiv.<id>) are DataCite DOIs: resolve them through arXiv directly
    am = re.match(r"10\.48550/arxiv\.(\d{4}\.\d{4,5})", ref.get("doi") or "", re.I)
    if am and not ref.get("arxiv"):
        ref = dict(ref, arxiv=am.group(1))
    # 1. DOI given
    if ref.get("doi") and not am:
        status, res = http_get("https://api.crossref.org/works/" + ref["doi"])
        if res and res.get("message"):
            paper = crossref_to_paper(res["message"])
            if not paper["abstract"]:
                abstract, src = fetch_abstract(paper["doi"], paper["title"])
                if abstract:
                    paper["abstract"], paper["source"] = abstract, "crossref+" + src
            return paper, "ok"
        if status == 404:
            st2, csl = doi_csl(ref["doi"])             # not a Crossref DOI - DataCite, mEDRA, ...?
            if csl and csl.get("title"):
                paper = csl_to_paper(csl, ref["doi"])
                if not paper["abstract"]:
                    abstract, src = fetch_abstract(paper["doi"], paper["title"])
                    if abstract:
                        paper["abstract"], paper["source"] = abstract, "doi.org+" + src
                return paper, "ok"
            if st2 == 404 and not ref.get("arxiv"):
                return None, ("DOI %s is not registered with any DOI registration agency (checked Crossref and doi.org) - "
                              "possibly fabricated or mistyped" % ref["doi"])
            if not ref.get("arxiv"):
                return None, "the DOI registry could not be reached (HTTP %s) - try re-analysing later" % (st2 or "timeout")
        elif not ref.get("arxiv"):
            return None, "the scholarly index could not be reached (HTTP %s) - try re-analysing later" % (status or "timeout")
    # 2. arXiv identifier in the reference
    if ref.get("arxiv"):
        e = (arxiv or {}).get(ref["arxiv"]) or (arxiv_batch([ref["arxiv"]]).get(ref["arxiv"]))
        if e:
            return dict(e), "ok"
    best, best_score = None, 0.0
    # 3. Crossref bibliographic search with the whole reference string
    query = re.sub(r"https?://\S+|\bdoi:\S+|PMID:?\s*\d+|PMCID:?\s*\w+", " ", ref.get("raw", ""))
    query = re.sub(r"^\[?\d+[\].]\s*", "", query).strip()[:400]
    if query:
        res = http_json("https://api.crossref.org/works", {"query.bibliographic": query, "rows": 5})
        for cand in ((res or {}).get("message") or {}).get("items", []):
            pd = crossref_to_paper(cand)
            sc = match_score(ref, pd["title"], pd["year"], pd["authors"])
            if sc > best_score:
                best, best_score = pd, sc
    # 4. Semantic Scholar title match (good coverage of conference papers, includes abstracts)
    if best_score < 0.8 and ref.get("title") and len(ref["title"].split()) >= 2:
        res = http_json("https://api.semanticscholar.org/graph/v1/paper/search/match",
                        {"query": ref["title"][:300], "fields": "title,year,abstract,authors,venue,externalIds"})
        for cand in (res or {}).get("data", [])[:1]:
            authors = ["%s, %s." % (a["name"].split()[-1], a["name"][:1]) for a in cand.get("authors", []) if a.get("name")]
            sc = match_score(ref, cand.get("title", ""), cand.get("year"), authors)
            if sc > best_score:
                ext = cand.get("externalIds") or {}
                doi = (ext.get("DOI") or "").lower()
                best, best_score = {"key": doi or "s2:" + str(cand.get("paperId")), "title": cand.get("title", ""), "authors": authors,
                                    "year": cand.get("year"), "venue": cand.get("venue", ""), "doi": doi,
                                    "url": ("https://doi.org/" + doi) if doi else ("https://arxiv.org/abs/" + ext["ArXiv"] if ext.get("ArXiv") else ""),
                                    "abstract": cand.get("abstract") or "", "sections": [], "cites": [], "source": "semanticscholar",
                                    "simulated": False}, sc
    # 5. arXiv title search (preprints that are not in Crossref)
    if best_score < 0.8 and ref.get("title") and len(ref["title"].split()) >= 2:
        for e in arxiv_query({"search_query": 'ti:"%s"' % re.sub(r'["]', "", ref["title"])[:200], "max_results": 3}):
            sc = match_score(ref, e["title"], e["year"], e["authors"])
            if sc > best_score:
                best, best_score = dict(e), sc
    if not best:
        busy = [h for h in ("api.semanticscholar.org", "export.arxiv.org") if _host_blocked_until.get(h, 0) > time.time()]
        if busy:
            return None, ("no matching record found, but %s was rate-limiting requests - re-analyse later for a complete check"
                          % " and ".join("Semantic Scholar" if "semantic" in h else "arXiv" for h in busy))
        return None, "no record in Crossref, Semantic Scholar or arXiv matches this reference"
    if not best.get("abstract"):
        abstract, src = fetch_abstract(best.get("doi", ""), best.get("title", ""))
        if abstract:
            best["abstract"], best["source"] = abstract, best.get("source", "") + "+" + src
    return best, "ok"


def resolve_reference(db, ref: Dict[str, Any], live: bool, arxiv: Optional[Dict[str, Dict[str, Any]]] = None) -> Tuple[Optional[Paper], str]:
    doi = ref.get("doi", "")
    for cp in CORPUS:
        if doi and doi == cp["doi"]:
            return get_or_create_paper(db, demo_paper_dict(cp)), "ok"
    if not doi:
        for cp in CORPUS:
            if ref.get("title") and sim_title(ref["title"], cp["title"]) >= 0.8:
                return get_or_create_paper(db, demo_paper_dict(cp)), "ok"
    if doi:
        existing = db.query(Paper).filter(Paper.doi == doi).first()
        if existing and (existing.abstract or existing.simulated):
            return existing, "ok"
    if ref.get("arxiv"):
        existing = db.query(Paper).filter(Paper.key == "arxiv:" + ref["arxiv"]).first()
        if existing:
            return existing, "ok"
    if doi.startswith("10.5555/cvdemo"):
        return None, "DOI %s does not exist in any index (not found in the demo corpus or Crossref)" % doi
    if not live:
        return None, "Live lookup disabled - source could not be retrieved"
    pd, reason = live_lookup_reference(ref, arxiv)
    if not pd:
        return None, reason
    p = get_or_create_paper(db, pd)
    if not p.abstract and pd.get("abstract"):          # an earlier lookup stored the record without an abstract
        with _db_lock:
            p.abstract, p.source = pd["abstract"], pd.get("source", p.source)
            db.commit()
    return p, "ok"


def demo_paper_dict(cp: Dict[str, Any]) -> Dict[str, Any]:
    return dict(cp, source="demo", simulated=True, url="")


def check_metadata(ref: Dict[str, Any], paper: Optional[Paper], reason: str) -> Tuple[str, List[Dict[str, str]]]:
    """Distinguish 'confirmed mismatch' (paper found, details differ) from 'could not verify'.
    Checks are made against the full reference text, so imperfect parsing does not create false mismatches."""
    if not paper:
        kind = "not_found" if ref.get("doi") and "could not be reached" not in reason else "unverified"
        return kind, [{"field": "existence", "severity": "unverified", "message": "Could not be verified: " + reason}]
    issues = []
    authors = jl(paper.authors, [])
    raw_tokens = _norm_tokens(ref.get("raw", ""))
    title_tokens = _norm_tokens(paper.title or "")
    if title_tokens and len(title_tokens & raw_tokens) / float(len(title_tokens)) < 0.6:
        issues.append({"field": "title", "severity": "mismatch", "claimed": ref.get("title", ""), "actual": paper.title,
                       "message": "Cited title differs from the registered title"})
    # a preprint and its published version are often a year apart, so allow +-1 year
    if ref.get("year") and paper.year and abs(int(ref["year"]) - int(paper.year)) >= 2:
        issues.append({"field": "year", "severity": "mismatch", "claimed": str(ref["year"]), "actual": str(paper.year),
                       "message": "Publication year is incorrect (cited %s, actual %s)" % (ref["year"], paper.year)})
    fa = strip_accents(ref.get("first_author") or "")
    fa_tokens = [re.sub(r"[^a-z]", "", t.lower()) for t in re.split(r"[\s,]+", fa) if re.search(r"[a-z]", t)]
    fa_tokens = [t for t in fa_tokens if len(t) > 1]
    if fa_tokens and authors:
        surnames = {re.sub(r"[^a-z]", "", strip_accents(a.split(",")[0]).lower()) for a in authors}
        if not any(t in surnames for t in fa_tokens):
            issues.append({"field": "authors", "severity": "mismatch", "claimed": ref.get("authors", ""), "actual": "; ".join(authors),
                           "message": "Author '%s' does not appear in the paper's author list" % (ref.get("first_author") or "")})
    if paper.simulated:
        actual_venue = (paper.venue or "").replace(DEMO_VENUE_SUFFIX, "")
        if (ref.get("venue") and actual_venue and ref["venue"].lower() not in actual_venue.lower()
                and actual_venue.lower() not in ref["venue"].lower() and sim_title(ref["venue"], actual_venue) < 0.3):
            issues.append({"field": "venue", "severity": "mismatch", "claimed": ref["venue"], "actual": paper.venue,
                           "message": "Journal / venue does not match the publication record"})
    return ("mismatch" if issues else "verified"), issues


# ---------------------------------------------------------------------------
# Verification engine
# ---------------------------------------------------------------------------
def paper_passages(p: Paper) -> List[Dict[str, Any]]:
    out = []
    if p.abstract:
        for s in split_sentences(p.abstract):
            out.append({"text": s, "section": "Abstract", "page": 1 if p.simulated else None})
    for sec in jl(p.sections, []):
        for s in split_sentences(sec["text"]):
            out.append({"text": s, "section": sec["name"], "page": sec.get("page")})
    return out


def compare_numbers(claim: str, passages: List[Dict[str, Any]], best: Dict[str, Any]) -> List[Dict[str, Any]]:
    results = []
    cnums = parse_numbers(claim)
    for cn in cnums:
        found = None
        for ps in passages:
            for en in parse_numbers(ps["text"]):
                tol = 0.5 if cn["kind"] != "number" else max(0.01 * cn["value"], 0.001)
                if abs(en["value"] - cn["value"]) <= tol:
                    found = (ps, en)
                    break
            if found:
                break
        if found:
            results.append({"claimed": cn["raw"], "actual": found[1]["raw"], "difference": 0, "match": True,
                            "passage": found[0]["text"], "section": found[0]["section"], "page": found[0]["page"],
                            "verdict": "Numerical value matches the source"})
            continue
        # No equal value anywhere: look for the same metric (e.g. "accuracy") reported with a different value.
        # Prefer passages that mention a metric word from the claim; fall back to the best passage.
        claim_metrics = [w for w in METRIC_WORDS if w in claim.lower()]
        chosen, cand = None, None
        for ps in ([] if cn.get("word") else [best] + [p for p in passages if p is not best]):
            same_kind = [en for en in parse_numbers(ps["text"]) if not en.get("word") and (en["kind"] == cn["kind"] or
                         (cn["kind"] in ("percent", "pp") and en["kind"] in ("percent", "pp"))) and (en["ctx"] & cn["ctx"])]
            same_kind.sort(key=lambda e: -len(e["ctx"] & cn["ctx"]))      # the value reported in the most similar context
            if not same_kind:
                continue
            low = ps["text"].lower()
            metric_pos = [low.find(w) for w in claim_metrics if w in low]
            if metric_pos:  # first numeric value that follows / sits nearest the shared metric word
                mp = min(metric_pos)
                chosen, cand = ps, min(same_kind, key=lambda e: abs(e["pos"] - mp) + (0 if e["pos"] >= mp else 40))
                break
            if ps is best and not claim_metrics and len(same_kind[0]["ctx"] & cn["ctx"]) >= 2:
                chosen, cand = ps, same_kind[0]
                break
        if not cand:
            results.append({"claimed": cn["raw"], "actual": None, "difference": None, "match": None, "passage": best["text"],
                            "section": best["section"], "page": best["page"], "verdict": "Source passage does not report this figure"})
            continue
        diff = round(abs(cand["value"] - cn["value"]), 2)
        unit = " percentage points" if cn["kind"] in ("percent", "pp") else ""
        results.append({"claimed": cn["raw"], "actual": cand["raw"], "difference": diff, "difference_label": "%g%s" % (diff, unit),
                        "match": False, "passage": chosen["text"], "section": chosen["section"], "page": chosen["page"],
                        "verdict": "Contradictory numerical evidence"})
    return results


def has_negation(text: str) -> bool:
    t = LIMIT_RE.sub(" ", text)  # hedged limitation phrases are not contradictions
    return bool(NEG_RE.search(t))


def absolute_terms(text: str) -> List[str]:
    found = []
    for m in ABSOLUTE_RE.finditer(text):
        before = text[max(0, m.start() - 12): m.start()].lower()
        if "not " in before:
            continue
        found.append(m.group(0))
    return found


def evaluate_rules(claim: str, paper: Paper) -> Dict[str, Any]:
    """Rule-based evaluation of one claim against one paper. Never invents text: every evidence item is a passage of the paper."""
    ct = tokens(claim)
    passages = paper_passages(paper)
    meta_text = (paper.title or "") + " " + (paper.abstract or "")
    topic = overlap(ct, meta_text)
    source_scope = "full text (simulated demo paper)" if paper.simulated else ("abstract only" if paper.abstract else "metadata only")
    base = {"paper_id": paper.id, "source_scope": source_scope, "chain": {}, "outdated": {}, "numeric": []}
    if not passages and paper.title and len(ct & tokens(paper.title)) >= 2:
        return dict(base, verdict="PARTIALLY SUPPORTED", confidence=0.35,
                    evidence=[{"text": paper.title, "section": "Title", "page": None, "label": "partial", "score": 0.5, "inline_cites": []}],
                    explanation="The cited paper was found and its title matches the subject of this statement (“%s”), but no abstract or "
                                "full text is openly available, so the specific detail could not be checked." % paper.title,
                    mismatch={"citation_matched": True, "topic_match": True, "claim_supported": None, "overgeneralized": None,
                              "contradictory": None, "label": "Title-level match only"})
    if not passages:
        return dict(base, verdict="NEEDS HUMAN REVIEW", confidence=0.2, evidence=[],
                    explanation="The cited paper was found (%s) but no abstract or full text is openly available. "
                                "Source unavailable - manual verification required." % (paper.title or "untitled"),
                    mismatch={"citation_matched": True, "topic_match": None, "claim_supported": None, "overgeneralized": None,
                              "contradictory": None, "label": "Source text unavailable"})
    cnums = {n["value"] for n in parse_numbers(claim)}
    scored = []
    for ps in passages:
        o = overlap(ct, ps["text"])
        bonus = 0.35 if cnums and any(abs(n["value"] - v) <= 0.5 for n in parse_numbers(ps["text"]) for v in cnums) else 0.0
        scored.append((o + (bonus if o >= 0.2 else 0), o, ps))
    scored.sort(key=lambda x: -x[0])
    best_score, best_ov, best = scored[0]
    top = [s for s in scored[:3] if s[1] >= 0.15] or [scored[0]]
    lim_passages = [ps for ps in passages if LIMIT_RE.search(ps["text"])]

    ev = evidence_item

    mismatch = {"citation_matched": True, "topic_match": True, "claim_supported": False, "overgeneralized": False, "contradictory": False}
    # 1. Topic mismatch (an abstract is short, so for live papers require a much lower overlap before calling it off-topic)
    if (best_ov < 0.25 and topic < 0.2) if paper.simulated else (best_ov < 0.08 and topic < 0.08):
        mismatch.update(topic_match=False, label="Topic mismatch")
        return dict(base, verdict="UNSUPPORTED", confidence=round(0.7 + 0.25 * (1 - max(best_ov, topic)), 2),
                    evidence=[ev(best, "none", best_ov)], mismatch=mismatch, _scored=scored, _limits=lim_passages, _absolutes=[], _topic=topic,
                    explanation="The cited paper exists, but it is about a different topic (“%s”). None of its passages discuss the "
                                "subject of this claim, so the citation does not support it. Consider a more relevant source." % paper.title)
    numeric = compare_numbers(claim, [s[2] for s in scored[:6]], best) if best_ov >= 0.25 else []
    num_bad = [n for n in numeric if n["match"] is False]
    num_missing = [n for n in numeric if n["match"] is None]
    claim_neg, ev_neg = has_negation(claim), has_negation(best["text"])
    absolutes = absolute_terms(claim)
    evidence = []
    verdict, conf, expl = None, 0.5, ""
    same_polarity = [s2 for s2 in scored[:4] if s2[1] >= max(0.35, best_ov * 0.85) and has_negation(s2[2]["text"]) == claim_neg]
    # 2. Contradiction by negation (not when another passage of the same paper states the claim's polarity)
    if best_ov >= (0.35 if paper.simulated else 0.45) and claim_neg != ev_neg and not same_polarity:
        verdict = "CONTRADICTORY"
        conf = round(min(0.92, 0.55 + best_ov * 0.5), 2)
        mismatch.update(contradictory=True, label="Contradictory findings")
        evidence.append(ev(best, "contradict", best_ov))
        expl = ("The source directly states the opposite of the claim. The claim asserts %s, while the paper reports: “%s”"
                % ("a negative finding" if claim_neg else "a positive finding", ev(best, "", 0)["text"]))
    # 3. Contradiction by numbers
    elif num_bad:
        n = num_bad[0]
        verdict = "CONTRADICTORY"
        conf = 0.9 if best_ov >= 0.35 else 0.7
        mismatch.update(contradictory=True, label="Statistical misrepresentation")
        num_ps = next((p for p in passages if p["text"] == n["passage"]), best)
        evidence.append(ev(num_ps, "contradict", overlap(ct, num_ps["text"])))
        expl = ("Numerical discrepancy: the claim states %s, but the cited paper reports %s (difference: %s). The source does not "
                "support the stated figure." % (n["claimed"], n["actual"], n.get("difference_label", n["difference"])))
    else:
        numbers_confirmed = bool(numeric) and all(n["match"] for n in numeric)
        if (best_ov >= 0.45 and not num_missing) or (numbers_confirmed and best_ov >= 0.3):
            verdict, conf = "SUPPORTED", round(min(0.95, 0.55 + max(best_ov, 0.45) * 0.45), 2)
            evidence.append(ev(best, "support", best_ov))
            mismatch.update(claim_supported=True, label="Citation matched")
            expl = "The cited paper directly states this finding%s." % (
                " and the reported figures match (%s)" % ", ".join(n["claimed"] for n in numeric) if numeric else "")
        elif best_ov >= 0.3:
            verdict, conf = "PARTIALLY SUPPORTED", round(0.45 + best_ov * 0.3, 2)
            evidence.append(ev(best, "partial", best_ov))
            mismatch.update(claim_supported=False, label="Claim only partially supported")
            expl = ("The paper discusses the same topic and partially overlaps with the claim, but no passage states it directly"
                    + ("; the claimed figure (%s) is not reported in the source" % num_missing[0]["claimed"] if num_missing else "") + ".")
        elif not paper.simulated and max(best_ov, topic) >= 0.1:
            verdict, conf = "PARTIALLY SUPPORTED", round(0.4 + best_ov * 0.3, 2)
            evidence.append(ev(best, "partial", best_ov))
            mismatch.update(claim_supported=False, label="Abstract does not restate claim")
            expl = ("The cited paper is on this topic, but its abstract does not restate this specific statement. Only the abstract "
                    "was available, so the detail may be in the body of the paper - check the full text if this point is critical")
        else:
            verdict, conf = "UNSUPPORTED", round(0.55 + (0.3 - best_ov), 2)
            evidence.append(ev(best, "none", best_ov))
            mismatch.update(label="Claim not supported")
            expl = ("The paper is on a related topic, but none of its passages make this claim. Similar topic is not the same as "
                    "supporting evidence.")
        # Overgeneralisation: absolute wording + documented limitations
        if verdict in ("SUPPORTED", "PARTIALLY SUPPORTED") and absolutes and lim_passages:
            verdict = "PARTIALLY SUPPORTED"
            conf = round(min(conf, 0.75), 2)
            mismatch.update(overgeneralized=True, claim_supported=False, label="Overgeneralized conclusion")
            evidence = [dict(evidence[0], label="partial")] + [ev(lp, "partial", overlap(ct, lp["text"])) for lp in lim_passages[:1]]
            expl = ("The paper supports a narrower version of this claim. The claim uses absolute wording (“%s”), but the "
                    "authors explicitly limit their conclusion: “%s”" % ("”, “".join(absolutes), lim_passages[0]["text"]))
    # supporting numeric passages that were not already shown
    for n in numeric:
        if n["match"] and all(e["text"] != n["passage"] for e in evidence):
            evidence.append({"text": n["passage"], "section": n["section"], "page": n["page"], "label": "support", "score": 1.0, "inline_cites": []})
    for s in top[1:]:
        if all(e["text"] != ev(s[2], "", 0)["text"] for e in evidence) and len(evidence) < 4:
            lab = "contradict" if (has_negation(s[2]["text"]) != claim_neg and s[1] >= 0.35) else ("partial" if s[1] >= 0.3 else "none")
            evidence.append(ev(s[2], lab, s[1]))
    if not paper.simulated:
        conf = round(conf * 0.85, 2)  # abstract-only evidence is weaker
        expl += " (Assessment based on the paper's abstract; full text was not available.)"
    return dict(base, verdict=verdict, confidence=conf, explanation=expl, evidence=evidence, numeric=numeric, mismatch=mismatch,
                _scored=scored, _limits=lim_passages, _absolutes=absolutes, _topic=topic)


def evidence_item(ps: Dict[str, Any], label: str, score: float) -> Dict[str, Any]:
    inline = INLINE_CORPUS_RE.findall(ps["text"])
    return {"text": INLINE_CORPUS_RE.sub(lambda m: cite_label(m.group(1)), ps["text"]), "section": ps["section"], "page": ps["page"],
            "label": label, "score": round(score, 2), "inline_cites": inline}


# ---------------------------------------------------------------------------
# Claim verification model (local, CPU): a DeBERTa-v3 NLI model fine-tuned on SciFact + Citation-Integrity
# (jedick/DeBERTa-v3-base-mnli-fever-anli-scifact-citint, MIT licence). It reads the paper text and the claim and
# outputs P(SUPPORT), P(NEI), P(REFUTE). Measured on SciFact dev (340 claim-paper pairs): macro-F1 0.82 vs 0.48 for
# the rule engine alone. Loaded once in a background thread; if torch/transformers are not installed, CiteVerify
# silently falls back to the rule engine.
# ---------------------------------------------------------------------------
VERIFIER_MODEL = os.getenv("VERIFIER_MODEL", "jedick/DeBERTa-v3-base-mnli-fever-anli-scifact-citint")
VERIFIER_ENABLED = os.getenv("VERIFIER", "on").lower() not in ("off", "false", "0")
T_REFUTE, T_SUPPORT = 0.75, 0.10          # decision thresholds, tuned on SciFact train (never on the test data)
T_LEAN_REFUTE, T_SENT_REFUTE, T_SENT_OVERLAP = 0.5, 0.95, 0.3   # "leaning contradiction" confirmed by one clear sentence


class Verifier:
    def __init__(self):
        self.state = "off" if not VERIFIER_ENABLED else "not loaded"
        self.error = ""
        self._lock = threading.Lock()
        self._ready = threading.Event()
        self._thread: Optional[threading.Thread] = None

    def start(self):
        if self.state == "off" or self._thread:
            return
        self.state = "loading"
        self._thread = threading.Thread(target=self._load, daemon=True)
        self._thread.start()

    def _load(self):
        try:
            import torch
            from transformers import AutoModelForSequenceClassification, AutoTokenizer
            torch.set_num_threads(max(1, (os.cpu_count() or 2) // 2))
            self.torch = torch
            self.tok = AutoTokenizer.from_pretrained(VERIFIER_MODEL)
            self.model = AutoModelForSequenceClassification.from_pretrained(VERIFIER_MODEL).eval()
            names = {i: l.lower() for i, l in self.model.config.id2label.items()}
            self.i_sup = next(i for i, l in names.items() if l.startswith(("support", "entail")))
            self.i_ref = next(i for i, l in names.items() if l.startswith(("refute", "contra")))
            self.i_nei = next(i for i in names if i not in (self.i_sup, self.i_ref))
            self.state = "ready"
        except Exception as e:                       # missing packages, no network on first download, ...
            self.state, self.error = "unavailable", "%s: %s" % (type(e).__name__, str(e)[:200])
            print("[verifier] falling back to the rule engine -", self.error)
        finally:
            self._ready.set()

    def ready(self, wait: float = 0.0) -> bool:
        if self.state == "off":
            return False
        self.start()
        if wait:
            self._ready.wait(wait)
        return self.state == "ready"

    def score(self, premises: List[str], claim: str) -> List[Tuple[float, float, float]]:
        """(P(support), P(nei), P(refute)) for each premise against the claim. Premise first, as the model was trained."""
        with self._lock, self.torch.no_grad():
            enc = self.tok(premises, [claim] * len(premises), truncation="only_first", max_length=512, padding=True, return_tensors="pt")
            probs = self.torch.softmax(self.model(**enc).logits.float(), dim=-1).tolist()
        return [(p[self.i_sup], p[self.i_nei], p[self.i_ref]) for p in probs]


VERIFIER = Verifier()
VERIFIER.start()


def clean_claim(text: str) -> str:
    t = CITE_NUM_RE.sub(" ", text)
    t = CITE_AY_RE.sub(" ", t)
    return re.sub(r"\s+([.,;:])", r"\1", re.sub(r"\s+", " ", t)).strip()


def paper_premise(paper: Paper) -> str:
    parts = [paper.title or "", paper.abstract or ""] + [sec["text"] for sec in jl(paper.sections, [])]
    return INLINE_CORPUS_RE.sub("", ". ".join(p.strip().rstrip(".") for p in parts if p and p.strip())) + "."


# ---------------------------------------------------------------------------
# Grounding checks around the model. The model judges meaning; these deterministic checks catch the failure modes we
# measured on real papers: support "hallucinated" for an unrelated paper, a figure the paper never reports, a figure
# taken from a different setting, an effect claimed for a subgroup the paper excludes, and a claim that only echoes
# what the paper says was *previously believed*.
# ---------------------------------------------------------------------------
GENERIC_SCI = None


def _generic_sci() -> set:
    global GENERIC_SCI
    if GENERIC_SCI is None:
        GENERIC_SCI = tokens(
            "model models network networks neural deep learning learned machine algorithm algorithms data dataset datasets method "
            "methods result results performance rate rates ratio level levels score scores accuracy accurate achieve achieved reach "
            "reached show showed shown high higher highest low lower lowest increase increased decrease decreased reduce reduced "
            "reduction effect effects effective efficacy patient patients participant participants study trial trials group groups "
            "using use used based approach system systems task tasks train trained training test tested testing set compare compared "
            "comparable comparison significant significantly average mean median total number new large small improve improved "
            "improvement analysis evaluate evaluated evaluation classify classified classification detect detected detection predict "
            "predicted prediction outcome outcomes risk human humans level image images clinical associated association across "
            "per year years day days month months time times early late first second major minor common rare overall pushed "
            "outperform outperformed performed perform better worse best state art previous prior current proposed present "
            "demonstrate demonstrated provide provided found finding findings role factor factors type types case cases value values")
    return GENERIC_SCI


def specific_terms(text: str) -> set:
    """Content words that identify what a claim is about (names, diseases, methods), not general research vocabulary."""
    return tokens(text) - _generic_sci() - {stem(w) for w in WORD_NUMS}


def topic_grounding(claim: str, paper: Paper) -> Tuple[float, int, int]:
    """(share of the claim's specific terms that occur in the paper, number shared, number of specific terms)."""
    spec = specific_terms(claim)
    if not spec:
        return 1.0, 0, 0
    shared = spec & tokens(paper_premise(paper))
    return len(shared) / float(len(spec)), len(shared), len(spec)


def _num_equal(cn: Dict[str, Any], en: Dict[str, Any]) -> bool:
    tol = 0.5 if cn["kind"] != "number" else max(0.01 * cn["value"], 0.001)
    if abs(en["value"] - cn["value"]) <= tol:
        return True
    # 84% == 0.84
    if cn["kind"] in ("percent", "pp") and en["kind"] == "number" and en["value"] <= 1:
        return abs(en["value"] * 100 - cn["value"]) <= 0.5
    if en["kind"] in ("percent", "pp") and cn["kind"] == "number" and cn["value"] <= 1:
        return abs(cn["value"] * 100 - en["value"]) <= 0.5
    return False


def claim_figures(claim: str) -> List[Dict[str, Any]]:
    """Numbers in a claim that are measurements, not part of a name (Covid-19, GPT-3, mRNA-1273, 3D, 1st)."""
    clean = INLINE_CORPUS_RE.sub("", CITE_NUM_RE.sub("", claim))
    out = []
    for n in parse_numbers(claim):
        i = n["pos"]
        if not n.get("word"):
            if i >= 2 and clean[i - 1] == "-" and clean[i - 2].isalpha():
                continue
            j = i + len(n["raw"].split()[0])
            if j < len(clean) and clean[j].isalpha() and not n["raw"][-1:].isalpha():
                continue
        out.append(n)
    return out


def unreported_figures(claim: str, paper: Paper) -> List[str]:
    pnums = parse_numbers(paper_premise(paper))
    return [cn["raw"] for cn in claim_figures(claim) if not any(_num_equal(cn, en) for en in pnums)]


EXCLUDED_GROUP_RE = re.compile(r"\b(?:but|and|whereas|while)\s+not\s+(?:among|in|for|with)\s+([^.;:()]{6,140})", re.I)
BACKGROUND_RE = re.compile(
    r"^(?:background:?\s*)?(?:there is (?:a )?(?:large|broad|general|wide|widespread|common|growing|strong)?\s*(?:consent|consensus|"
    r"agreement|belief)|it is (?:widely|commonly|generally|often|usually|traditionally) (?:believed|assumed|accepted|thought|held|"
    r"claimed)|conventional wisdom|it has (?:long )?been (?:believed|assumed|thought|argued)|traditionally,|the common belief)", re.I)


def excluded_group_conflict(claim: str, passages: List[Dict[str, Any]]) -> Optional[Tuple[Dict[str, Any], str]]:
    """The paper reports an effect 'but not among <group>' while the claim asserts the effect for that group."""
    claim_c = clean_claim(claim)
    ct = tokens(claim_c)
    for ps in passages:
        for m in EXCLUDED_GROUP_RE.finditer(ps["text"]):
            span = m.group(1)
            st = tokens(span)
            if len(st) < 2 or len(st & ct) / float(len(st)) < 0.75:
                continue
            span_words = {w.lower().strip(",") for w in span.split()}
            rest = " ".join(w for w in claim_c.split() if w.lower().strip(",.") not in span_words)
            if has_negation(rest):
                continue                               # the claim itself says there was no effect in that group
            if overlap(ct - st, ps["text"][:m.start()]) < 0.4:
                continue                               # a different finding
            return ps, span.strip()
    return None


def local_number_conflict(claim: str, sent: List[Tuple[Dict[str, Any], Tuple[float, float, float]]]) -> Optional[Tuple[int, str]]:
    """The sentence that best matches the claim reports a different figure for the same setting, and the model, reading
    that sentence alone, is confident it contradicts the claim (e.g. 41.8 BLEU quoted for English-German when the paper
    reports 28.4 there; 41.8 is its English-French result)."""
    figs = [n for n in claim_figures(claim) if not n.get("word")]
    if not figs or not sent:
        return None
    ct = tokens(clean_claim(claim))
    i = max(range(len(sent)), key=lambda k: overlap(ct, sent[k][0]["text"]))
    text = sent[i][0]["text"]
    if overlap(ct, text) < 0.6 or sent[i][1][2] < 0.95:
        return None
    snums = [n for n in parse_numbers(text) if not n.get("word")]
    for cn in figs:
        if any(_num_equal(cn, en) for en in snums):
            continue
        rival = [en for en in snums if en["kind"] == cn["kind"] or {en["kind"], cn["kind"]} <= {"percent", "pp"}]
        if rival:
            return i, "%s (the paper reports %s here)" % (cn["raw"], rival[0]["raw"])
    return None


def hybrid_judgement(claim: str, paper: Paper, r: Dict[str, Any]) -> Dict[str, Any]:
    """Combine the model's judgement with the rule engine. The model decides meaning (support / contradiction / no evidence);
    deterministic checks keep the final say on numbers, scope, topic grounding, overgeneralisation, citation chains and
    outdated research."""
    m = r.get("mismatch") or {}
    claim_c = clean_claim(claim)
    scored = r["_scored"]
    cands = [x[2] for x in scored[:5]]
    premise = paper_premise(paper)
    premises = [premise] + [INLINE_CORPUS_RE.sub("", c["text"]) for c in cands]
    # sentences that report what was *previously believed* are context, not the paper's findings
    background = [x for x in split_sentences(paper.abstract or "") if BACKGROUND_RE.search(x)]
    if background:
        findings = premise
        for b in background:
            findings = findings.replace(b, " ")
        premises.append(findings)
    probs = VERIFIER.score(premises, claim_c)
    S, N, R = probs[-1] if background else probs[0]
    sent = list(zip(cands, probs[1:1 + len(cands)]))
    out = dict(r, engine="nli", model_probs={"support": round(S, 3), "nei": round(N, 3), "refute": round(R, 3)})
    scope = "" if paper.simulated else " (Assessment based on the paper's abstract; full text was not available.)"
    damp = 1.0 if paper.simulated else 0.92

    def ev_list(primary_idx, primary_label):
        items = [evidence_item(sent[primary_idx][0], primary_label, max(sent[primary_idx][1][0], sent[primary_idx][1][2]))]
        for c, (s_, n_, r_) in sent:
            if len(items) >= 3 or c is sent[primary_idx][0]:
                continue
            lab = "support" if s_ >= 0.5 else ("contradict" if r_ >= 0.5 else ("partial" if s_ + r_ >= 0.3 else None))
            if lab:
                items.append(evidence_item(c, lab, max(s_, r_)))
        for n in r.get("numeric", []):          # keep the passages that confirm the numbers
            if n.get("match") and all(e["text"] != n["passage"] for e in items):
                items.append({"text": n["passage"], "section": n["section"], "page": n["page"], "label": "support", "score": 1.0, "inline_cites": []})
        return items

    def off_topic(conf):
        k = max(range(len(sent)), key=lambda i: sent[i][1][0] + sent[i][1][2])
        out.update(verdict="UNSUPPORTED", confidence=round(min(0.97, conf * damp), 2), evidence=[evidence_item(sent[k][0], "none", 0)],
                   mismatch=dict(m, topic_match=False, claim_supported=False, contradictory=False, label="Topic mismatch"),
                   explanation="The cited paper exists, but it is about a different topic (“%s”) and contains no evidence for this "
                               "claim. Consider a more relevant source.%s" % (paper.title, scope))
        return out

    # 1. Topic grounding: the claim's specific subject must appear in the paper. Guards against the model reading
    #    support into an unrelated paper (seen on real papers: a BERT benchmark claim "supported" by a smartwatch study).
    share, shared, nspec = topic_grounding(claim_c, paper)
    if not paper.simulated and nspec >= 2 and shared == 0 and scored[0][1] < 0.3:
        return off_topic(max(N, 0.8))

    # 2. Effect claimed for a subgroup the paper explicitly excludes ("... but not among those receiving no respiratory support")
    ex = excluded_group_conflict(claim_c, [x[2] for x in scored[:8]])
    if ex:
        ps, span = ex
        out.update(verdict="CONTRADICTORY", confidence=round(0.9 * damp, 2), evidence=[evidence_item(ps, "contradict", 1.0)],
                   mismatch=dict(m, contradictory=True, claim_supported=False, topic_match=True, label="Contradictory findings"),
                   explanation="The paper reports this effect only for some patients, and explicitly not among %s - the group this "
                               "claim applies it to. The paper reports: “%s”%s" % (span, evidence_item(ps, "", 0)["text"], scope))
        return out

    # 3. Rules that keep the final say: a figure contradicted by the paper, or absolute wording against stated limitations
    if m.get("label") == "Statistical misrepresentation" or m.get("overgeneralized"):
        out["confidence"] = round(min(0.97, max(r["confidence"], R if m.get("label") == "Statistical misrepresentation" else r["confidence"])), 2)
        return out

    # 4. A figure quoted for the wrong setting: the best-matching sentence reports a different value
    loc = local_number_conflict(claim_c, sent)
    if loc:
        k, what = loc
        out.update(verdict="CONTRADICTORY", confidence=round(min(0.97, sent[k][1][2] * damp), 2), evidence=ev_list(k, "contradict"),
                   mismatch=dict(m, contradictory=True, claim_supported=False, topic_match=True, label="Statistical misrepresentation"),
                   explanation="Numerical discrepancy: the claim states %s. The figure in the claim belongs to a different result or "
                               "setting. The paper reports: “%s”%s" % (what, evidence_item(sent[k][0], "", 0)["text"], scope))
        return out

    # 5. The model's verdict. A contradiction needs a confident model, or a model leaning that way plus a relevant
    #    sentence that it reads as a clear contradiction.
    strong_sentence = [i for i, (c, (s_, n_, r_)) in enumerate(sent) if r_ >= T_SENT_REFUTE and overlap(tokens(claim_c), c["text"]) >= T_SENT_OVERLAP]
    if (R >= T_REFUTE and R > S) or (R >= T_LEAN_REFUTE and R > S and strong_sentence):
        k = max(range(len(sent)), key=lambda i: sent[i][1][2])
        out.update(verdict="CONTRADICTORY", confidence=round(min(0.97, R * damp), 2), evidence=ev_list(k, "contradict"),
                   mismatch=dict(m, contradictory=True, claim_supported=False, topic_match=True, label="Contradictory findings"),
                   explanation="The cited paper contradicts this claim: its findings point the other way (contradiction probability "
                               "%d%%). The paper reports: “%s”%s" % (round(R * 100), evidence_item(sent[k][0], "", 0)["text"], scope))
    elif S >= T_SUPPORT:
        k = max(range(len(sent)), key=lambda i: sent[i][1][0])
        missing = unreported_figures(claim_c, paper)
        if missing:
            # the paper supports the general statement, but not the specific figure the claim adds
            out.update(verdict="PARTIALLY SUPPORTED", confidence=round(min(0.85, 0.5 + 0.35 * S) * damp, 2), evidence=ev_list(k, "partial"),
                       mismatch=dict(m, claim_supported=False, contradictory=False, topic_match=True, label="Claim only partially supported"),
                       explanation="The cited paper supports the general statement, but the figure%s %s %s not reported anywhere in the "
                                   "available text. Check the full paper or cite the source of the figure. Closest passage: “%s”%s" % (
                                       "s" if len(missing) > 1 else "", ", ".join(missing), "are" if len(missing) > 1 else "is",
                                       evidence_item(sent[k][0], "", 0)["text"], scope))
        else:
            nums = [n["claimed"] for n in r.get("numeric", []) if n.get("match")]
            out.update(verdict="SUPPORTED", confidence=round(min(0.97, max(S, 0.55) * damp), 2), evidence=ev_list(k, "support"),
                       mismatch=dict(m, claim_supported=True, contradictory=False, topic_match=True, label="Citation matched"),
                       explanation="The cited paper supports this claim (support probability %d%%)%s. Key passage: “%s”%s" % (
                           round(S * 100), "; the reported figures match (%s)" % ", ".join(nums) if nums else "",
                           evidence_item(sent[k][0], "", 0)["text"], scope))
    else:
        k = max(range(len(sent)), key=lambda i: sent[i][1][0] + sent[i][1][2])
        topical = max(scored[0][1], r.get("_topic", 0)) >= (0.25 if paper.simulated else 0.1)
        if not paper.simulated and nspec >= 2 and share < 0.25 and shared < 2 and not (specific_terms(claim_c) & tokens(paper.title or "")):
            topical = False                            # shares only general research vocabulary with the paper
        if m.get("label") == "Topic mismatch" or not topical:
            return off_topic(N)
        elif paper.simulated:
            out.update(verdict="UNSUPPORTED", confidence=round(min(0.97, N), 2), evidence=[evidence_item(sent[k][0], "none", 0)],
                       mismatch=dict(m, topic_match=True, claim_supported=False, contradictory=False, label="Claim not supported"),
                       explanation="The paper is on a related topic, but none of its passages establish this claim. A similar topic "
                                   "is not the same as supporting evidence.")
        else:
            out.update(verdict="PARTIALLY SUPPORTED", confidence=round(min(0.8, 0.4 + 0.4 * (1 - N)), 2), evidence=[evidence_item(sent[k][0], "partial", 0)],
                       mismatch=dict(m, topic_match=True, claim_supported=False, contradictory=False, label="Abstract does not restate claim"),
                       explanation="The cited paper is on this topic, but its abstract does not establish this specific statement. Only the "
                                   "abstract was available, so the detail may be in the body of the paper - check the full text if this point is critical.")
    return out


def evaluate(claim: str, paper: Paper, db=None, depth: int = 0) -> Dict[str, Any]:
    """Verify one claim against one paper: rule engine + local verification model + citation-chain tracing."""
    r = evaluate_rules(claim, paper)
    if "_scored" in r and VERIFIER.ready():
        try:
            r = hybrid_judgement(claim, paper, r)
        except Exception as e:                          # never fail an analysis because of the model
            print("[verifier] rule-engine fallback for one claim:", type(e).__name__, str(e)[:120])
    r.setdefault("engine", "rules")
    result = {k: v for k, v in r.items() if not k.startswith("_")}

    # Citation chain: the evidence passage itself relies on another (corpus) paper -> check the original study too
    if depth == 0 and db is not None and result["verdict"] in ("SUPPORTED", "PARTIALLY SUPPORTED") and result.get("evidence"):
        inline = result["evidence"][0].get("inline_cites") or []
        if inline and inline[0] in CORPUS_BY_KEY:
            orig = db.query(Paper).filter(Paper.key == inline[0]).first() or get_or_create_paper(db, demo_paper_dict(CORPUS_BY_KEY[inline[0]]))
            sub = evaluate(claim, orig, db, depth=1)
            ok = sub["verdict"] in ("SUPPORTED", "PARTIALLY SUPPORTED")
            result["chain"] = {"via_paper_id": paper.id, "original_paper_id": orig.id, "original_title": orig.title,
                               "original_verdict": sub["verdict"], "traceable": ok, "original_evidence": sub["evidence"][:1],
                               "original_explanation": sub["explanation"]}
            if not ok:
                result["verdict"] = "NEEDS HUMAN REVIEW"
                result["confidence"] = 0.6
                result["mismatch"] = dict(result.get("mismatch") or {}, label="Untraceable citation chain")
                result["explanation"] = ("Suspicious citation chain. The cited paper (“%s”) repeats this claim, but it relies on an "
                                         "earlier study (“%s”) whose original evidence does not support it: %s Please cite and check "
                                         "the original source." % (paper.title, orig.title, sub["explanation"]))
    return result


def cite_label(key: str) -> str:
    p = CORPUS_BY_KEY.get(key)
    if not p:
        return ""
    first = p["authors"][0].split(",")[0]
    return "(%s%s, %d)" % (first, " et al." if len(p["authors"]) > 1 else "", p["year"])


def find_newer_research(db, claim: str, paper: Paper, live: bool) -> List[Paper]:
    ct = tokens(claim)
    newer = []
    for cp in CORPUS:
        if cp["year"] >= (paper.year or 0) + 5 and cp["key"] != paper.key:
            if overlap(ct, cp["title"] + " " + cp["abstract"] + " " + " ".join(s["text"] for s in cp["sections"])) >= 0.4:
                newer.append(get_or_create_paper(db, demo_paper_dict(cp)))
    if not newer and live and not paper.simulated and paper.year:
        q = " ".join(sorted(re.findall(r"[A-Za-z]{5,}", claim), key=len, reverse=True)[:6])
        res = http_json("https://api.crossref.org/works", {"query.bibliographic": q, "rows": 5,
                                                           "filter": "from-pub-date:%d,has-abstract:true" % (paper.year + 5)})
        for item in ((res or {}).get("message") or {}).get("items", [])[:5]:
            pd = crossref_to_paper(item)
            if pd["abstract"] and overlap(ct, pd["title"] + " " + pd["abstract"]) >= 0.5:
                newer.append(get_or_create_paper(db, pd))
            if len(newer) >= 2:
                break
    return newer


# ---------------------------------------------------------------------------
# Optional LLM refinement (Claude). Rule engine is always the fallback.
# ---------------------------------------------------------------------------
_llm_client = None


def llm_available() -> bool:
    return bool(os.getenv("ANTHROPIC_API_KEY")) and os.getenv("LLM_ENABLED", "true").lower() == "true"


def get_llm():
    global _llm_client
    if _llm_client is None:
        import anthropic
        _llm_client = anthropic.Anthropic()
    return _llm_client


def llm_json(prompt: str, schema: dict, max_tokens: int = 2000) -> Optional[dict]:
    if not llm_available():
        return None
    try:
        resp = get_llm().beta.messages.create(
            model=ANTHROPIC_MODEL, max_tokens=max_tokens,
            betas=["server-side-fallback-2026-07-01"], fallbacks="default",
            output_config={"effort": "low", "format": {"type": "json_schema", "schema": schema}},
            messages=[{"role": "user", "content": prompt}])
        if resp.stop_reason == "refusal":
            return None
        text = next((b.text for b in resp.content if getattr(b, "type", "") == "text"), "")
        return json.loads(text) if text else None
    except Exception as e:  # network, auth, rate limit: degrade to rules
        print("[llm] falling back to rules:", type(e).__name__, str(e)[:200])
        return None


LLM_VERDICT_SCHEMA = {
    "type": "object",
    "properties": {
        "verdict": {"type": "string", "enum": ["SUPPORTED", "PARTIALLY SUPPORTED", "UNSUPPORTED", "CONTRADICTORY", "NEEDS HUMAN REVIEW"]},
        "passage_ids": {"type": "array", "items": {"type": "integer"}},
        "passage_labels": {"type": "array", "items": {"type": "string", "enum": ["support", "contradict", "partial", "none"]}},
        "explanation": {"type": "string"},
        "confidence": {"type": "number"},
    },
    "required": ["verdict", "passage_ids", "passage_labels", "explanation", "confidence"],
    "additionalProperties": False,
}


def llm_refine(claim: str, paper: Paper, rule: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    passages = paper_passages(paper)[:40]
    if not passages or rule.get("chain", {}).get("traceable") is False:
        return None
    numbered = "\n".join("[%d] (%s) %s" % (i, p["section"], INLINE_CORPUS_RE.sub("", p["text"])) for i, p in enumerate(passages))
    prompt = (
        "You verify whether a cited paper supports a student's claim. Use ONLY the numbered passages below; do not use outside "
        "knowledge and never quote text that is not in a passage. Topic similarity alone is not support: distinguish direct support, "
        "partial support (narrower scope, overgeneralised wording, figure not reported), contradiction (opposite finding or different "
        "number) and missing evidence. Deterministic numeric checks are provided as facts.\n\n"
        "CLAIM: %s\n\nPAPER: %s (%s)\nPASSAGES:\n%s\n\nNUMERIC CHECKS: %s\nRULE-ENGINE VERDICT: %s\n\n"
        "Return the verdict, the ids of the passages that are the evidence (most relevant first, max 3), a label for each chosen "
        "passage, a 1-3 sentence explanation a student can understand, and a confidence between 0 and 1 reflecting strength of the "
        "available evidence." % (claim, paper.title, paper.year, numbered, jd([{k: n[k] for k in ("claimed", "actual", "verdict")} for n in rule["numeric"]]), rule["verdict"]))
    out = llm_json(prompt, LLM_VERDICT_SCHEMA, 1500)
    if not out:
        return None
    ids = [i for i in out["passage_ids"] if isinstance(i, int) and 0 <= i < len(passages)][:3]
    if not ids:
        return None
    labels = out["passage_labels"] + ["partial"] * 3
    evidence = [{"text": INLINE_CORPUS_RE.sub("", passages[i]["text"]), "section": passages[i]["section"], "page": passages[i]["page"],
                 "label": labels[k], "score": 1.0, "inline_cites": []} for k, i in enumerate(ids)]
    if any(n["match"] is False for n in rule["numeric"]):
        out["verdict"] = "CONTRADICTORY"  # numbers are checked deterministically, never overridden
    return {"verdict": out["verdict"], "explanation": out["explanation"], "confidence": round(max(0.05, min(0.97, float(out["confidence"]))), 2),
            "evidence": evidence}


# ---------------------------------------------------------------------------
# Analysis pipeline
# ---------------------------------------------------------------------------
STAGES = ["Reading document", "Extracting claims", "Mapping citations", "Retrieving original papers", "Comparing evidence", "Generating report"]


def set_stage(db, doc: Document, stage: int, pause: float):
    doc.stage = stage
    db.commit()
    if pause:
        time.sleep(pause)


def verify_claim_record(db, c: Claim, ref_row: Optional[Reference], paper: Optional[Paper], live: bool, use_llm: bool):
    labels = jl(c.citation_labels, [])
    c.ref_id = ref_row.id if ref_row else None
    c.paper_id = paper.id if paper else None
    c.chain, c.outdated, c.numeric = "{}", "{}", "[]"
    c.engine = "rules"
    if not labels:
        c.verdict, c.confidence = "NEEDS HUMAN REVIEW", 0.3
        c.explanation = "This factual/statistical statement has no citation. Add a source that reports this figure, or remove the claim."
        c.evidence = "[]"
        c.mismatch = jd({"citation_matched": False, "label": "Missing citation"})
        return
    if not ref_row:
        c.verdict, c.confidence = "NEEDS HUMAN REVIEW", 0.3
        c.explanation = "Citation %s does not match any entry in the reference list." % ", ".join(labels)
        c.evidence = "[]"
        c.mismatch = jd({"citation_matched": False, "label": "Citation not in reference list"})
        return
    if not paper:
        issues = jl(ref_row.issues, [])
        c.verdict, c.confidence = "NEEDS HUMAN REVIEW", 0.2
        c.explanation = "Source unavailable - manual verification required. %s" % (issues[0]["message"] if issues else "")
        c.evidence = jd([{"text": "No evidence could be retrieved for this reference.", "section": "", "page": None, "label": "none", "score": 0}])
        c.mismatch = jd({"citation_matched": False, "label": "Source unavailable"})
        return
    r = evaluate(c.text, paper, db)
    c.engine = r.get("engine", "rules")
    if use_llm:
        refined = llm_refine(c.text, paper, r)
        if refined:
            r.update(refined)
            c.engine = "llm"
    # Outdated research check (only after support is established; old is not automatically wrong)
    if paper.year and CURRENT_YEAR - paper.year >= OUTDATED_YEARS and r["verdict"] in ("SUPPORTED", "PARTIALLY SUPPORTED"):
        newer = find_newer_research(db, c.text, paper, live)
        items, changed = [], False
        for np_ in newer:
            sub = evaluate(c.text, np_, None, depth=1)
            differs = sub["verdict"] == "CONTRADICTORY"
            changed = changed or differs
            items.append({"paper_id": np_.id, "title": np_.title, "year": np_.year, "verdict_vs_claim": sub["verdict"],
                          "finding": sub["evidence"][0]["text"] if sub["evidence"] else "", "differs": differs,
                          "numeric": sub["numeric"]})
        r["outdated"] = {"year": paper.year, "age": CURRENT_YEAR - paper.year, "newer": items, "changed": changed,
                         "note": ("Potentially outdated evidence - newer research is available and reports different findings."
                                  if changed else ("Older source, but newer research is consistent with it." if items else
                                                   "Older source; no newer related study was found. Age alone does not make it invalid."))}
        if changed:
            r["verdict"] = "POTENTIALLY OUTDATED"
            nn = [i for i in items if i["differs"]][0]
            r["explanation"] = ("The %d source supports the claim, but it is %d years old and newer research (%s, %s) reports a different "
                                "result: “%s” Check whether the conclusion still holds." % (paper.year, CURRENT_YEAR - paper.year,
                                nn["title"], nn["year"], nn["finding"]))
            r["confidence"] = 0.7
    c.verdict, c.confidence, c.explanation = r["verdict"], r["confidence"], r["explanation"]
    c.evidence, c.numeric, c.mismatch = jd(r["evidence"]), jd(r["numeric"]), jd(r["mismatch"])
    c.outdated, c.chain = jd(r.get("outdated") or {}), jd(r.get("chain") or {})


ASSERTION_CUES = re.compile(r"\b(outperform\w*|achiev\w*|improv\w*|reduc\w*|increas\w*|decreas\w*|exceed\w*|better|best|superior|eliminat\w*|"
                            r"guarantee\w*|prove[sdn]?|always|never|all|caus\w*|lead[s]? to|significant\w*|more|less|higher|lower|faster)\b", re.I)


def citation_window(claim: str, label: str) -> str:
    """Words around the citation marker for `label` - the concept the citation is attached to."""
    for m in re.finditer(r"\[([^\]]+)\]", claim):
        nums = []
        for part in re.split(r"\s*,\s*", m.group(1)):
            if re.match(r"^\d+\s*[-–]\s*\d+$", part):
                a, b = [int(x) for x in re.split(r"\s*[-–]\s*", part)]
                nums += [str(i) for i in range(a, b + 1)]
            else:
                nums.append(part.strip())
        if label in nums:
            before = re.sub(r"\[[^\]]*\]", " ", claim[: m.start()]).split()[-8:]
            after = re.sub(r"\[[^\]]*\]", " ", claim[m.end():]).split()[:8]
            return " ".join(before + after)
    if " " in label:                                   # author-year
        name = label.rsplit(" ", 1)[0]
        i = claim.find(name)
        if i >= 0:
            return " ".join(claim[:i].split()[-8:] + claim[i:].split()[:10])
    return claim


def attribution_result(claim: str, label: str, paper: Paper) -> Optional[Dict[str, Any]]:
    """Background citations ('we employ a residual connection [11]', 'long short-term memory [13]') credit a method or concept
    to the paper that introduced it. They are supported when the cited paper is about that concept - no finding is claimed."""
    if not paper or parse_numbers(claim):
        return None
    window = citation_window(claim, label)
    clause = re.split(r"[;:]|,\s+(?:but|while|whereas|however)\b", re.sub(r"\[[^\]]*\]", " ", claim))
    if ASSERTION_CUES.search(window) or any(ASSERTION_CUES.search(c) or has_negation(c) for c in clause if set(tokens(c)) & tokens(window)):
        return None                                    # the citation backs an empirical assertion: evaluate the evidence instead
    w = tokens(window)
    title_t = tokens(paper.title or "")
    authors = {re.sub(r"[^a-z]", "", strip_accents(a.split(",")[0]).lower())[:5] for a in jl(paper.authors, [])}
    shared = (w & title_t) | (w & authors)
    if not paper.abstract and (w & authors):
        return {"paper_id": paper.id, "verdict": "PARTIALLY SUPPORTED", "confidence": 0.45, "numeric": [], "chain": {}, "outdated": {},
                "evidence": [{"text": paper.title, "section": "Title", "page": None, "label": "partial", "score": 0.5, "inline_cites": []}],
                "mismatch": {"citation_matched": True, "topic_match": True, "claim_supported": None, "overgeneralized": None,
                             "contradictory": None, "label": "Author attribution (no abstract)"},
                "explanation": ("The statement correctly attributes this work to the cited authors (“%s”). No abstract is openly "
                                "available, so the details described could not be checked against the paper." % paper.title)}
    if not w or not (len(shared) >= 2 or (len(shared) >= 1 and len(w) <= 4) or (title_t and len(w & title_t) / float(len(title_t)) >= 0.5)):
        return None
    passages = paper_passages(paper)
    best = max(passages, key=lambda ps: len(tokens(ps["text"]) & w), default=None) if passages else None
    evidence = ([{"text": best["text"], "section": best["section"], "page": best["page"], "label": "support", "score": 1.0, "inline_cites": []}]
                if best and tokens(best["text"]) & w else [{"text": paper.title, "section": "Title", "page": None, "label": "support", "score": 1.0, "inline_cites": []}])
    return {"paper_id": paper.id, "verdict": "SUPPORTED", "confidence": 0.72 if paper.abstract else 0.6, "evidence": evidence, "numeric": [],
            "chain": {}, "outdated": {}, "mismatch": {"citation_matched": True, "topic_match": True, "claim_supported": True,
                                                       "overgeneralized": False, "contradictory": False, "label": "Attribution citation"},
            "explanation": ("Attribution citation: the statement credits “%s” to the cited paper (“%s”), which is about that method or "
                            "concept. No specific finding is claimed, so no further evidence is needed." % (window.strip(" ,.;"), paper.title))}


VERDICT_RANK = {"SUPPORTED": 5, "POTENTIALLY OUTDATED": 4, "PARTIALLY SUPPORTED": 3, "NEEDS HUMAN REVIEW": 2, "UNSUPPORTED": 1, "CONTRADICTORY": 0}


def verify_claim_multi(db, c: Claim, candidates: List[Tuple[str, Reference, Optional[Paper]]], live: bool, use_llm: bool):
    """Evaluate a claim against every cited source it names and keep the strongest result.
    A claim citing [16, 11, 13] is supported if any of those sources supports it."""
    resolved = [(lab, row, p) for lab, row, p in candidates if p is not None]
    if not resolved:
        verify_claim_record(db, c, candidates[0][1] if candidates else None, None, live, use_llm)
        return
    results = []
    for lab, row, p in resolved[:6]:
        tmp = Claim(doc_id=c.doc_id, idx=c.idx, text=c.text, citation_labels=c.citation_labels)
        verify_claim_record(db, tmp, row, p, live, use_llm)
        att = attribution_result(c.text, lab, p) if tmp.verdict not in ("SUPPORTED", "CONTRADICTORY", "POTENTIALLY OUTDATED") else None
        if att:
            tmp.ref_id, tmp.paper_id, tmp.engine = row.id, p.id, "rules"
            tmp.verdict, tmp.confidence, tmp.explanation = att["verdict"], att["confidence"], att["explanation"]
            tmp.evidence, tmp.numeric, tmp.mismatch, tmp.outdated, tmp.chain = jd(att["evidence"]), "[]", jd(att["mismatch"]), "{}", "{}"
        results.append(tmp)
    # contradictions are never hidden by another supporting source
    contra = [t for t in results if t.verdict == "CONTRADICTORY"]
    best = contra[0] if contra else max(results, key=lambda t: (VERDICT_RANK.get(t.verdict, 0), t.confidence or 0))
    for f in ("ref_id", "paper_id", "verdict", "confidence", "explanation", "evidence", "numeric", "mismatch", "outdated", "chain", "engine"):
        setattr(c, f, getattr(best, f))
    if len(resolved) > 1:
        c.explanation += " (Strongest of %d cited sources checked.)" % len(results)


def analyze_document(doc_id: int, live: bool = LIVE_LOOKUP, pause: float = 0.6):
    db = SessionLocal()
    doc = db.get(Document, doc_id)
    VERIFIER.ready(wait=600)                    # use the verification model when available (rules otherwise)
    try:
        set_stage(db, doc, 1, pause)
        body, ref_entries = split_body_references(doc.text)
        set_stage(db, doc, 2, pause)
        claims = extract_claims(body)
        if not claims:
            raise ValueError("No claims or citations were detected. Make sure the document contains in-text citations such as [1] or (Author, 2020).")
        set_stage(db, doc, 3, pause)
        db.query(Reference).filter(Reference.doc_id == doc.id).delete()
        db.query(Claim).filter(Claim.doc_id == doc.id).delete()
        parsed = [parse_reference(r, i + 1) for i, r in enumerate(ref_entries)]
        set_stage(db, doc, 4, 0)
        arxiv = arxiv_batch([pr["arxiv"] for pr in parsed if pr.get("arxiv")]) if live else {}
        lookups: List[Tuple[Optional[Paper], str]] = []
        if live and len(parsed) > 1:
            with ThreadPoolExecutor(max_workers=4) as ex:
                lookups = list(ex.map(lambda pr: _resolve_in_thread(pr, live, arxiv), parsed))
            lookups = [(db.get(Paper, pid) if pid else None, reason) for pid, reason in lookups]
        else:
            lookups = [resolve_reference(db, pr, live, arxiv) for pr in parsed]
        busy = [i for i, (p_, reason) in enumerate(lookups) if not p_ and "rate-limiting" in reason]
        if busy:                                       # one more, slower pass once the services have cooled down
            time.sleep(max(0, max(_host_blocked_until.values() or [0]) - time.time()) + 1)
            for i in busy:
                lookups[i] = resolve_reference(db, parsed[i], live, arxiv)
        if live:
            for p_, _r in lookups:
                if p_ and not p_.simulated and not p_.abstract:
                    abstract, src = fetch_abstract(p_.doi or "", p_.title or "")
                    if abstract:
                        with _db_lock:
                            p_.abstract, p_.source = abstract, (p_.source or "") + "+" + src
                            db.commit()
        ref_rows = []
        for pr, (paper, reason) in zip(parsed, lookups):
            status, issues = check_metadata(pr, paper, reason)
            row = Reference(doc_id=doc.id, idx=len(ref_rows) + 1, label=pr["label"], raw=pr["raw"], title=pr["title"],
                            authors=pr["authors"], year=pr["year"], doi=pr["doi"], venue=pr["venue"],
                            paper_id=paper.id if paper else None, meta_status=status, issues=jd(issues))
            db.add(row)
            ref_rows.append((pr, row, paper))
        db.commit()
        time.sleep(pause)
        set_stage(db, doc, 5, pause)
        use_llm = llm_available()

        def find_ref(label):
            for pr, row, paper in ref_rows:
                if pr["label"] == label:
                    return row, paper
            if " " in label:  # author-year
                name, year = label.rsplit(" ", 1)
                for pr, row, paper in ref_rows:
                    if name.lower() in (pr["authors"] or "").lower() and str(pr["year"]) == year:
                        return row, paper
            return None, None

        for i, cl in enumerate(claims):
            c = Claim(doc_id=doc.id, idx=i + 1, text=cl["text"], citation_labels=jd(cl["labels"]))
            candidates = []
            for lab in cl["labels"]:
                ref_row, paper = find_ref(lab)
                if ref_row:
                    candidates.append((lab, ref_row, paper))
            if cl["labels"] and candidates:
                verify_claim_multi(db, c, candidates, live, use_llm)
            else:
                verify_claim_record(db, c, None, None, live, use_llm)
            db.add(c)
        db.commit()
        set_stage(db, doc, 6, pause)
        doc.summary = jd(doc_summary(db, doc))
        doc.status = "analyzed"
        db.commit()
    except Exception as e:
        db.rollback()
        doc = db.get(Document, doc_id)
        doc.status, doc.error = "failed", str(e)[:500]
        db.commit()
    finally:
        db.close()


def _resolve_in_thread(pr, live, arxiv=None):
    db = SessionLocal()
    try:
        p, reason = resolve_reference(db, pr, live, arxiv)
        return (p.id if p else None), reason
    finally:
        db.close()


def doc_summary(db, doc: Document) -> Dict[str, Any]:
    claims = db.query(Claim).filter(Claim.doc_id == doc.id).all()
    refs = db.query(Reference).filter(Reference.doc_id == doc.id).all()
    counts = {v: 0 for v in VERDICTS}
    for c in claims:
        counts[c.verdict] = counts.get(c.verdict, 0) + 1
    total = len(claims) or 1
    reliability = round(100 * (counts["SUPPORTED"] + 0.5 * counts["PARTIALLY SUPPORTED"] + 0.5 * counts["POTENTIALLY OUTDATED"]) / total)
    risky = counts["UNSUPPORTED"] + counts["CONTRADICTORY"] + counts["NEEDS HUMAN REVIEW"]
    return {"claims": len(claims), "references": len(refs), "counts": counts, "reliability": reliability,
            "suspicious_refs": len([r for r in refs if r.meta_status != "verified"]),
            "mapped_refs": len([r for r in refs if r.paper_id]), "risk": "high" if risky >= 3 else ("medium" if risky else "low")}


# ---------------------------------------------------------------------------
# Serialisation helpers
# ---------------------------------------------------------------------------
def user_dict(u: User) -> Dict[str, Any]:
    return {"id": u.id, "email": u.email, "name": u.name, "role": u.role, "program": u.program}


def doc_dict(d: Document, db=None) -> Dict[str, Any]:
    out = {"id": d.id, "owner_id": d.owner_id, "title": d.title, "filename": d.filename, "filetype": d.filetype, "size": d.size,
           "version": d.version, "root_id": d.root_id or d.id, "prev_id": d.prev_id, "status": d.status, "stage": d.stage,
           "stages": STAGES, "error": d.error, "demo": d.demo, "summary": jl(d.summary, {}),
           "created_at": iso(d.created_at), "submitted_at": iso(d.submitted_at), "reviewed_at": iso(d.reviewed_at)}
    if db is not None:
        owner = db.get(User, d.owner_id)
        out["owner_name"] = owner.name if owner else ""
    return out


def iso(dt):
    return dt.isoformat() + "Z" if dt else None


def claim_dict(c: Claim, db=None, with_context=False) -> Dict[str, Any]:
    out = {"id": c.id, "doc_id": c.doc_id, "idx": c.idx, "text": c.text, "citation_labels": jl(c.citation_labels, []),
           "ref_id": c.ref_id, "paper_id": c.paper_id, "verdict": c.verdict, "confidence": c.confidence, "explanation": c.explanation,
           "evidence": jl(c.evidence, []), "numeric": jl(c.numeric, []), "mismatch": jl(c.mismatch, {}), "outdated": jl(c.outdated, {}),
           "chain": jl(c.chain, {}), "engine": c.engine, "review_status": c.review_status, "prof_verdict": c.prof_verdict,
           "prof_note": c.prof_note, "replacement": jl(c.replacement, {})}
    if with_context and db is not None:
        p = db.get(Paper, c.paper_id) if c.paper_id else None
        r = db.get(Reference, c.ref_id) if c.ref_id else None
        d = db.get(Document, c.doc_id)
        o = db.get(User, d.owner_id) if d else None
        out["paper"] = paper_to_dict(p) if p else None
        out["reference"] = ref_dict(r) if r else None
        out["doc_title"] = d.title if d else ""
        out["student_name"] = o.name if o else ""
        out["student_id"] = o.id if o else None
    return out


def ref_dict(r: Reference) -> Dict[str, Any]:
    return {"id": r.id, "idx": r.idx, "label": r.label, "raw": r.raw, "title": r.title, "authors": r.authors, "year": r.year,
            "doi": r.doi, "venue": r.venue, "paper_id": r.paper_id, "meta_status": r.meta_status, "issues": jl(r.issues, [])}


def notify(db, user_id: int, kind: str, title: str, body: str = "", link: str = ""):
    db.add(Notification(user_id=user_id, kind=kind, title=title, body=body, link=link))


def professors(db) -> List[User]:
    return db.query(User).filter(User.role == "professor").all()


def visible_doc(db, user: User, doc_id: int) -> Document:
    d = db.get(Document, doc_id)
    if not d:
        raise HTTPException(404, "Document not found")
    if user.role == "student" and d.owner_id != user.id:
        raise HTTPException(403, "Not your document")
    if user.role == "professor" and d.status in ("processing", "analyzed", "failed"):
        raise HTTPException(403, "This document has not been submitted for review")
    return d


REVIEW_STATES = ("submitted", "in_review", "reviewed", "revision_requested")

