# ---- documents ------------------------------------------------------------
def create_document(db, user: User, title: str, filename: str, filetype: str, size: int, text: str, parent_id: Optional[int], is_demo=False) -> Document:
    root_id, prev_id, version = None, None, 1
    if parent_id:
        parent = db.get(Document, parent_id)
        if not parent or parent.owner_id != user.id:
            raise HTTPException(404, "Original document not found")
        root_id = parent.root_id or parent.id
        latest = db.query(Document).filter((Document.root_id == root_id) | (Document.id == root_id)).order_by(Document.version.desc()).first()
        prev_id, version = latest.id, latest.version + 1
    d = Document(owner_id=user.id, title=title, filename=filename, filetype=filetype, size=size, text=text, root_id=root_id,
                 prev_id=prev_id, version=version, status="processing", demo=is_demo)
    db.add(d)
    db.commit()
    if not root_id:
        d.root_id = d.id
        db.commit()
    return d


@app.post("/api/documents/upload")
async def upload(background: BackgroundTasks, file: UploadFile = File(...), title: str = Form(""), parent_id: str = Form(""),
                 user: User = Depends(require_student)):
    data = await file.read()
    if not data:
        raise HTTPException(400, "The uploaded file is empty.")
    if len(data) > MAX_UPLOAD_MB * 1024 * 1024:
        raise HTTPException(413, "File is larger than %d MB." % MAX_UPLOAD_MB)
    try:
        text = extract_text(file.filename or "upload", data)
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(422, "Could not read this file. It may be corrupted, encrypted or a scanned image without text.")
    if len(text.strip()) < 100:
        raise HTTPException(422, "Very little text could be extracted. Scanned PDFs need OCR before verification.")
    db = SessionLocal()
    try:
        ext = (file.filename or "").rsplit(".", 1)[-1].upper()
        first_line = next((l.strip() for l in text.splitlines() if len(l.strip()) > 8), file.filename)
        d = create_document(db, user, title.strip() or first_line[:140], file.filename, ext, len(data), text,
                            int(parent_id) if parent_id else None)
        background.add_task(analyze_document, d.id)
        return doc_dict(d)
    finally:
        db.close()


@app.post("/api/documents/sample")
def sample(background: BackgroundTasks, variant: str = "original", parent_id: Optional[int] = None, user: User = Depends(require_student)):
    spec = SAMPLE_SPECS.get(variant, RIYA_ORIGINAL)
    text = build_document_text(spec)
    db = SessionLocal()
    try:
        d = create_document(db, user, spec["title"], "citeverify-sample-%s.docx" % variant, "DOCX", len(text.encode()), text, parent_id, True)
        background.add_task(analyze_document, d.id)
        return doc_dict(d)
    finally:
        db.close()


@app.get("/api/demo/sample-file")
def sample_file(variant: str = "original"):
    import docx
    spec = SAMPLE_SPECS.get(variant, RIYA_ORIGINAL)
    d = docx.Document()
    for i, line in enumerate(build_document_text(spec).split("\n")):
        if i == 0:
            d.add_heading(line, 1)
        elif line in ("Abstract", "References") or re.match(r"^\d\. ", line):
            d.add_heading(line, 2)
        elif line:
            d.add_paragraph(line)
    buf = io.BytesIO()
    d.save(buf)
    return Response(buf.getvalue(), media_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                    headers={"Content-Disposition": 'attachment; filename="citeverify-sample-%s.docx"' % variant})


@app.get("/api/documents")
def list_documents(user: User = Depends(current_user)):
    db = SessionLocal()
    try:
        q = db.query(Document)
        q = q.filter(Document.owner_id == user.id) if user.role == "student" else q.filter(Document.status.in_(REVIEW_STATES))
        return [doc_dict(d, db) for d in q.order_by(Document.created_at.desc()).all()]
    finally:
        db.close()


@app.get("/api/documents/{doc_id}")
def get_document(doc_id: int, user: User = Depends(current_user)):
    db = SessionLocal()
    try:
        d = visible_doc(db, user, doc_id)
        claims = db.query(Claim).filter(Claim.doc_id == d.id).order_by(Claim.idx).all()
        refs = db.query(Reference).filter(Reference.doc_id == d.id).order_by(Reference.idx).all()
        pids = {c.paper_id for c in claims if c.paper_id} | {r.paper_id for r in refs if r.paper_id}
        for c in claims:
            for n in jl(c.outdated, {}).get("newer", []):
                pids.add(n["paper_id"])
            ch = jl(c.chain, {})
            if ch:
                pids.add(ch["original_paper_id"])
        papers = {p.id: paper_to_dict(p) for p in db.query(Paper).filter(Paper.id.in_(pids)).all()} if pids else {}
        versions = db.query(Document).filter(Document.root_id == (d.root_id or d.id)).order_by(Document.version).all()
        fb = db.query(Feedback).filter(Feedback.doc_id == d.id).all()
        if user.role == "student":
            fb = [f for f in fb if f.status != "draft"]
        return {"document": doc_dict(d, db), "claims": [claim_dict(c) for c in claims], "references": [ref_dict(r) for r in refs],
                "papers": papers, "versions": [doc_dict(v) for v in versions if user.role == "student" or v.status in REVIEW_STATES],
                "feedback": [feedback_dict(f, db) for f in fb], "text": d.text}
    finally:
        db.close()


@app.delete("/api/documents/{doc_id}")
def delete_document(doc_id: int, user: User = Depends(require_student)):
    db = SessionLocal()
    try:
        d = visible_doc(db, user, doc_id)
        if d.status in ("submitted", "in_review"):
            raise HTTPException(400, "Submitted documents under review cannot be deleted.")
        db.query(Claim).filter(Claim.doc_id == d.id).delete()
        db.query(Reference).filter(Reference.doc_id == d.id).delete()
        db.delete(d)
        db.commit()
        return {"ok": True}
    finally:
        db.close()


@app.post("/api/documents/{doc_id}/reanalyze")
def reanalyze(doc_id: int, background: BackgroundTasks, user: User = Depends(require_student)):
    db = SessionLocal()
    try:
        d = visible_doc(db, user, doc_id)
        d.status, d.stage, d.error = "processing", 0, ""
        db.commit()
        background.add_task(analyze_document, d.id)
        return doc_dict(d)
    finally:
        db.close()


@app.post("/api/documents/{doc_id}/submit")
def submit_document(doc_id: int, user: User = Depends(require_student)):
    db = SessionLocal()
    try:
        d = visible_doc(db, user, doc_id)
        if d.status not in ("analyzed", "revision_requested"):
            raise HTTPException(400, "Only analyzed documents can be submitted (current status: %s)." % d.status)
        d.status, d.submitted_at = "submitted", datetime.utcnow()
        for p in professors(db):
            if d.version > 1:
                notify(db, p.id, "revision", "Revised document submitted", "%s submitted version %d of “%s”." % (user.name, d.version, d.title),
                       "/professor/revisions?doc=%d" % d.id)
            else:
                notify(db, p.id, "submission", "New submission", "%s submitted “%s” for review." % (user.name, d.title),
                       "/professor/evidence?doc=%d" % d.id)
        db.commit()
        return doc_dict(d)
    finally:
        db.close()


class StatusIn(BaseModel):
    status: str


@app.post("/api/documents/{doc_id}/status")
def set_doc_status(doc_id: int, body: StatusIn, user: User = Depends(require_professor)):
    if body.status not in ("in_review", "reviewed", "revision_requested"):
        raise HTTPException(400, "Invalid status")
    db = SessionLocal()
    try:
        d = visible_doc(db, user, doc_id)
        d.status = body.status
        if body.status in ("reviewed", "revision_requested"):
            d.reviewed_at = datetime.utcnow()
            title = "Submission reviewed" if body.status == "reviewed" else "Revision requested"
            msg = ("%s reviewed “%s”." if body.status == "reviewed" else "%s requested a revision of “%s”. Check the feedback and upload a revised version.") % (user.name, d.title)
            notify(db, d.owner_id, body.status, title, msg, "/student/feedback")
        db.commit()
        return doc_dict(d)
    finally:
        db.close()


@app.get("/api/documents/{doc_id}/compare")
def compare_versions(doc_id: int, user: User = Depends(current_user)):
    db = SessionLocal()
    try:
        new = visible_doc(db, user, doc_id)
        if not new.prev_id:
            raise HTTPException(400, "This document has no earlier version to compare with.")
        old = db.get(Document, new.prev_id)
        return build_comparison(db, old, new)
    finally:
        db.close()


GOOD = ("SUPPORTED",)
RANK = {"SUPPORTED": 3, "PARTIALLY SUPPORTED": 2, "POTENTIALLY OUTDATED": 2, "NEEDS HUMAN REVIEW": 1, "UNSUPPORTED": 0, "CONTRADICTORY": 0}


def build_comparison(db, old: Document, new: Document) -> Dict[str, Any]:
    oc = db.query(Claim).filter(Claim.doc_id == old.id).order_by(Claim.idx).all()
    nc = db.query(Claim).filter(Claim.doc_id == new.id).order_by(Claim.idx).all()
    used, rows = set(), []
    for o in oc:
        best, bs = None, 0.0
        for n in nc:
            if n.id in used:
                continue
            s = sim_title(o.text, n.text)
            if s > bs:
                best, bs = n, s
        if best and bs >= 0.3:
            used.add(best.id)
            same_text = bs > 0.95
            same_paper = o.paper_id == best.paper_id
            kind = "unchanged" if same_text and same_paper else "modified"
            delta = RANK.get(best.verdict, 0) - RANK.get(o.verdict, 0)
            rows.append({"type": kind, "old": claim_dict(o), "new": claim_dict(best), "similarity": round(bs, 2),
                         "citation_replaced": not same_paper, "improved": delta > 0, "regressed": delta < 0,
                         "outcome": "improved" if delta > 0 else ("regressed" if delta < 0 else ("still unresolved" if best.verdict not in GOOD else "unchanged"))})
        else:
            rows.append({"type": "removed", "old": claim_dict(o), "new": None, "outcome": "removed"})
    for n in nc:
        if n.id not in used:
            rows.append({"type": "new", "old": None, "new": claim_dict(n), "outcome": "new issue" if n.verdict not in GOOD else "new evidence"})
    so, sn = doc_summary(db, old), doc_summary(db, new)
    stats = {
        "claims_corrected": len([r for r in rows if r.get("improved")]),
        "citations_replaced": len([r for r in rows if r.get("citation_replaced")]),
        "new_evidence": len([r for r in rows if r["type"] == "new" and r["new"]["verdict"] in GOOD]),
        "unsupported_remaining": len([n for n in nc if n.verdict not in GOOD]),
        "new_issues": len([r for r in rows if (r["type"] == "new" and r["new"]["verdict"] not in GOOD) or r.get("regressed")]),
        "removed": len([r for r in rows if r["type"] == "removed"]),
        "reliability_before": so["reliability"], "reliability_after": sn["reliability"],
        "improvement": sn["reliability"] - so["reliability"],
    }
    return {"old": doc_dict(old), "new": doc_dict(new), "rows": rows, "stats": stats, "summary_old": so, "summary_new": sn}


