class ReplaceIn(BaseModel):
    paper_id: int


@app.post("/api/claims/{claim_id}/replace")
def replace_citation(claim_id: int, body: ReplaceIn, user: User = Depends(require_student)):
    """Only runs after the student explicitly approves a suggested paper."""
    db = SessionLocal()
    try:
        c = db.get(Claim, claim_id)
        if not c:
            raise HTTPException(404, "Claim not found")
        d = visible_doc(db, user, c.doc_id)
        if d.status in ("submitted", "in_review"):
            raise HTTPException(400, "This document is under review. Upload a revised version instead.")
        p = db.get(Paper, body.paper_id)
        if not p:
            raise HTTPException(404, "Paper not found")
        before = {"paper_id": c.paper_id, "verdict": c.verdict}
        if not jl(c.citation_labels, []):
            c.citation_labels = jd(["new"])
        ref = Reference(doc_id=d.id, idx=db.query(Reference).filter(Reference.doc_id == d.id).count() + 1, label="R%d" % c.idx,
                        raw=format_reference(dict(title=p.title, authors=jl(p.authors, []) or ["Unknown"], year=p.year or 0,
                                                       venue=p.venue, doi=p.doi)),
                        title=p.title, authors="; ".join(jl(p.authors, [])), year=p.year, doi=p.doi, venue=p.venue, paper_id=p.id,
                        meta_status="verified", issues="[]")
        db.add(ref)
        db.commit()
        verify_claim_record(db, c, ref, p, LIVE_LOOKUP, llm_available())
        c.replacement = jd({"from": before, "to_paper_id": p.id, "approved_at": iso(datetime.utcnow())})
        d.summary = jd(doc_summary(db, d))
        db.commit()
        return claim_dict(c, db, True)
    finally:
        db.close()


class ReviewIn(BaseModel):
    review_status: str
    prof_verdict: str = ""
    prof_note: str = ""


@app.patch("/api/claims/{claim_id}/review")
def review_claim(claim_id: int, body: ReviewIn, user: User = Depends(require_professor)):
    db = SessionLocal()
    try:
        c = db.get(Claim, claim_id)
        if not c:
            raise HTTPException(404, "Claim not found")
        d = visible_doc(db, user, c.doc_id)
        c.review_status, c.prof_verdict, c.prof_note = body.review_status, body.prof_verdict, body.prof_note
        if d.status == "submitted":
            d.status = "in_review"
        db.commit()
        return claim_dict(c, db, True)
    finally:
        db.close()


