EDGE_KIND = {"SUPPORTED": "support", "PARTIALLY SUPPORTED": "partial", "POTENTIALLY OUTDATED": "partial", "CONTRADICTORY": "contradict",
             "UNSUPPORTED": "contradict", "NEEDS HUMAN REVIEW": "review"}


@app.get("/api/network")
def network(doc_id: Optional[int] = None, user: User = Depends(current_user)):
    db = SessionLocal()
    try:
        q = db.query(Document)
        q = q.filter(Document.owner_id == user.id, Document.status != "processing") if user.role == "student" else q.filter(Document.status.in_(REVIEW_STATES))
        if doc_id:
            q = q.filter(Document.id == doc_id)
        docs = q.all()
        if user.role == "professor" and not doc_id:  # latest version per student document chain
            latest = {}
            for d in docs:
                k = d.root_id or d.id
                if k not in latest or d.version > latest[k].version:
                    latest[k] = d
            docs = list(latest.values())
        nodes, edges, paper_users = {}, [], {}
        for d in docs:
            owner = db.get(User, d.owner_id)
            sid = "s%d" % owner.id
            if user.role == "professor":
                nodes[sid] = {"id": sid, "type": "student", "label": owner.name, "data": {"user_id": owner.id}}
            for c in db.query(Claim).filter(Claim.doc_id == d.id).all():
                cid = "c%d" % c.id
                nodes[cid] = {"id": cid, "type": "claim", "label": c.text, "data": {"claim_id": c.id, "verdict": c.verdict, "doc": d.title, "student": owner.name}}
                if user.role == "professor":
                    edges.append({"source": sid, "target": cid, "kind": "authored"})
                if c.paper_id:
                    p = db.get(Paper, c.paper_id)
                    pid = "p%d" % p.id
                    paper_users.setdefault(pid, set()).add(owner.id)
                    nodes.setdefault(pid, {"id": pid, "type": "paper", "label": p.title, "data": {"paper_id": p.id, "year": p.year, "simulated": p.simulated, "claims": 0}})
                    nodes[pid]["data"]["claims"] += 1
                    edges.append({"source": cid, "target": pid, "kind": EDGE_KIND.get(c.verdict, "review"), "verdict": c.verdict})
                    for ck in jl(p.cites, []):
                        cp = db.query(Paper).filter(Paper.key == ck).first()
                        if cp:
                            cpid = "p%d" % cp.id
                            nodes.setdefault(cpid, {"id": cpid, "type": "cited", "label": cp.title, "data": {"paper_id": cp.id, "year": cp.year, "simulated": cp.simulated, "claims": 0}})
                            ch = jl(c.chain, {})
                            broken = ch and ch.get("original_paper_id") == cp.id and not ch.get("traceable")
                            e = {"source": pid, "target": cpid, "kind": "chain_broken" if broken else "cites"}
                            if e not in edges:
                                edges.append(e)
                    for n in jl(c.outdated, {}).get("newer", []):
                        npid = "p%d" % n["paper_id"]
                        nodes.setdefault(npid, {"id": npid, "type": "newer", "label": n["title"], "data": {"paper_id": n["paper_id"], "year": n["year"], "claims": 0}})
                        e = {"source": pid, "target": npid, "kind": "newer"}
                        if e not in edges:
                            edges.append(e)
                else:
                    nid = "u%d" % c.id
                    nodes[nid] = {"id": nid, "type": "missing", "label": "Source unavailable / no citation", "data": {}}
                    edges.append({"source": cid, "target": nid, "kind": "review", "verdict": c.verdict})
        for pid, users in paper_users.items():
            nodes[pid]["data"]["students"] = len(users)
            if nodes[pid]["type"] == "cited":
                nodes[pid]["type"] = "paper"
        return {"nodes": list(nodes.values()), "edges": edges}
    finally:
        db.close()


