@app.get("/api/student/overview")
def student_overview(user: User = Depends(require_student)):
    db = SessionLocal()
    try:
        docs = db.query(Document).filter(Document.owner_id == user.id).order_by(Document.created_at.desc()).all()
        claims = db.query(Claim).join(Document, Document.id == Claim.doc_id).filter(Document.owner_id == user.id).all()
        counts = {v: 0 for v in VERDICTS}
        for c in claims:
            counts[c.verdict] = counts.get(c.verdict, 0) + 1
        attention = [d for d in docs if jl(d.summary, {}).get("risk") in ("high", "medium") or d.status == "revision_requested"]
        total = len(claims) or 1
        reliability = round(100 * (counts["SUPPORTED"] + 0.5 * (counts["PARTIALLY SUPPORTED"] + counts["POTENTIALLY OUTDATED"])) / total) if claims else 0
        fb = db.query(Feedback).filter(Feedback.student_id == user.id, Feedback.status == "sent").count()
        refs = db.query(Reference).join(Document, Document.id == Reference.doc_id).filter(Document.owner_id == user.id).all()
        activity = []
        for d in docs[:6]:
            activity.append({"kind": "document", "title": d.title, "status": d.status, "at": iso(d.submitted_at or d.created_at), "doc_id": d.id})
        return {"documents": len(docs), "claims": len(claims), "counts": counts, "attention": len(attention), "reliability": reliability,
                "open_feedback": fb, "suspicious_refs": len([r for r in refs if r.meta_status != "verified"]),
                "recent": [doc_dict(d) for d in docs[:6]], "activity": activity}
    finally:
        db.close()


