# ---- feedback -----------------------------------------------------------------
def feedback_dict(f: Feedback, db) -> Dict[str, Any]:
    d = db.get(Document, f.doc_id)
    s = db.get(User, f.student_id)
    p = db.get(User, f.professor_id)
    c = db.get(Claim, f.claim_id) if f.claim_id else None
    return {"id": f.id, "doc_id": f.doc_id, "doc_title": d.title if d else "", "doc_version": d.version if d else 1,
            "student_id": f.student_id, "student_name": s.name if s else "",
            "professor_name": p.name if p else "", "claim_id": f.claim_id, "claim_text": c.text if c else "",
            "claim_verdict": c.verdict if c else "", "body": f.body, "comment": f.comment, "status": f.status,
            "created_at": iso(f.created_at), "sent_at": iso(f.sent_at), "addressed_at": iso(f.addressed_at)}


def template_feedback(c: Claim, db) -> str:
    p = db.get(Paper, c.paper_id) if c.paper_id else None
    nums = [n for n in jl(c.numeric, []) if n.get("match") is False]
    mm = jl(c.mismatch, {})
    od = jl(c.outdated, {})
    ch = jl(c.chain, {})
    short = c.text if len(c.text) < 110 else c.text[:107] + "..."
    title = "“%s”" % p.title if p else "the cited source"
    if nums:
        n = nums[0]
        return ("Your statement “%s” is not supported by the cited research paper. The original paper reports %s, not %s. "
                "Please revise the numerical claim or provide a more appropriate source." % (short, n["actual"], n["claimed"]))
    if ch and not ch.get("traceable", True):
        return ("The claim “%s” relies on a secondary source. %s cites %s, whose original evidence does not support the claim. "
                "Please consult and cite the original study, and report what it actually found." % (short, title, "“%s”" % ch.get("original_title")))
    if c.verdict == "CONTRADICTORY":
        return ("The cited paper %s reports the opposite of your statement “%s”. Please re-read the source's findings and "
                "revise the claim so it accurately reflects the evidence." % (title, short))
    if mm.get("label") == "Topic mismatch":
        return ("The source cited for “%s” (%s) is not about this topic, so it cannot support the claim. Please replace it with "
                "research that directly investigates this question." % (short, title))
    if mm.get("overgeneralized"):
        return ("Your claim “%s” generalises beyond what the cited study shows. The authors state limitations to their findings; "
                "please narrow the wording (e.g. specify the setting and sample) or add broader evidence." % short)
    if c.verdict == "POTENTIALLY OUTDATED":
        nn = [i for i in od.get("newer", []) if i.get("differs")]
        return ("The evidence for “%s” comes from a %s study. More recent research%s reports different results. Please "
                "consider updating the claim with current evidence." % (short, od.get("year"), " (%s, %s)" % (nn[0]["title"], nn[0]["year"]) if nn else ""))
    if mm.get("label") == "Missing citation":
        return "The statement “%s” presents a factual or statistical claim without a citation. Please add a source that reports it." % short
    if c.verdict == "NEEDS HUMAN REVIEW":
        return ("The reference supporting “%s” could not be verified (%s). Please check the citation details (authors, year, DOI) "
                "and confirm the source exists." % (short, c.explanation.split(". ")[0].lower()))
    if c.verdict == "UNSUPPORTED":
        return "The cited paper does not contain evidence for “%s”. Please provide a source that directly supports this statement." % short
    return "The claim “%s” is only partly supported by %s. Please clarify the scope of the claim." % (short, title)


class GenerateIn(BaseModel):
    doc_id: int
    claim_ids: Optional[List[int]] = None


@app.post("/api/feedback/generate")
def generate_feedback(body: GenerateIn, user: User = Depends(require_professor)):
    db = SessionLocal()
    try:
        d = visible_doc(db, user, body.doc_id)
        q = db.query(Claim).filter(Claim.doc_id == d.id)
        claims = [c for c in q.order_by(Claim.idx).all() if (body.claim_ids and c.id in body.claim_ids) or (not body.claim_ids and c.verdict != "SUPPORTED")]
        items = [{"claim_id": c.id, "claim_text": c.text, "verdict": c.verdict, "body": template_feedback(c, db)} for c in claims]
        summary = doc_summary(db, d)
        overall = ("Overall, %d of %d claims are fully supported by their cited sources (evidence reliability %d%%). The items below need "
                   "attention before this work meets the evidence standard." % (summary["counts"]["SUPPORTED"], summary["claims"], summary["reliability"]))
        engine_used = "rules"
        if llm_available() and items:
            schema = {"type": "object", "properties": {"overall": {"type": "string"}, "items": {"type": "array", "items": {"type": "string"}}},
                      "required": ["overall", "items"], "additionalProperties": False}
            prompt = ("Rewrite this academic feedback for a student so it is constructive, specific and concise. Keep every factual detail "
                      "(numbers, paper titles) exactly as given; do not add facts. Return one rewritten item per input item, in order.\n\n"
                      "OVERALL: %s\nITEMS:\n%s" % (overall, "\n".join("%d. %s" % (i + 1, it["body"]) for i, it in enumerate(items))))
            out = llm_json(prompt, schema, 3000)
            if out and len(out.get("items", [])) == len(items):
                overall = out["overall"]
                for it, txt in zip(items, out["items"]):
                    it["body"] = txt
                engine_used = "llm"
        return {"overall": overall, "items": items, "engine": engine_used}
    finally:
        db.close()


class FeedbackIn(BaseModel):
    doc_id: int
    claim_id: Optional[int] = None
    body: str
    comment: str = ""
    send: bool = False


@app.post("/api/feedback")
def save_feedback(body: FeedbackIn, user: User = Depends(require_professor)):
    db = SessionLocal()
    try:
        d = visible_doc(db, user, body.doc_id)
        f = Feedback(doc_id=d.id, student_id=d.owner_id, professor_id=user.id, claim_id=body.claim_id, body=body.body.strip(),
                     comment=body.comment.strip(), status="sent" if body.send else "draft", sent_at=datetime.utcnow() if body.send else None)
        db.add(f)
        if body.send:
            notify(db, d.owner_id, "feedback", "New professor feedback", "%s sent feedback on “%s”." % (user.name, d.title), "/student/feedback")
            if d.status == "submitted":
                d.status = "in_review"
        db.commit()
        return feedback_dict(f, db)
    finally:
        db.close()


