@app.get("/api/professor/overview")
def professor_overview(user: User = Depends(require_professor)):
    db = SessionLocal()
    try:
        students = db.query(User).filter(User.role == "student").all()
        docs = db.query(Document).filter(Document.status.in_(REVIEW_STATES)).order_by(Document.submitted_at.desc()).all()
        doc_ids = [d.id for d in docs]
        claims = db.query(Claim).filter(Claim.doc_id.in_(doc_ids)).all() if doc_ids else []
        counts = {v: 0 for v in VERDICTS}
        for c in claims:
            counts[c.verdict] = counts.get(c.verdict, 0) + 1
        refs = db.query(Reference).filter(Reference.doc_id.in_(doc_ids)).all() if doc_ids else []
        risk = {"low": 0, "medium": 0, "high": 0}
        for d in docs:
            risk[jl(d.summary, {}).get("risk", "low")] += 1
        total = len(claims) or 1
        integrity = round(100 * (counts["SUPPORTED"] + 0.5 * (counts["PARTIALLY SUPPORTED"] + counts["POTENTIALLY OUTDATED"])) / total) if claims else 0
        activity = []
        for d in docs[:8]:
            o = db.get(User, d.owner_id)
            activity.append({"title": d.title, "student": o.name, "status": d.status, "version": d.version, "at": iso(d.submitted_at), "doc_id": d.id})
        for f in db.query(Feedback).filter(Feedback.professor_id == user.id, Feedback.status != "draft").order_by(Feedback.created_at.desc()).limit(5):
            s = db.get(User, f.student_id)
            activity.append({"title": "Feedback " + ("addressed" if f.status == "addressed" else "sent") + " to " + s.name, "student": s.name,
                             "status": "feedback_" + f.status, "at": iso(f.addressed_at or f.sent_at), "doc_id": f.doc_id})
        activity.sort(key=lambda a: a["at"] or "", reverse=True)
        return {"students": len(students), "submissions": len(docs), "awaiting": len([d for d in docs if d.status == "submitted"]),
                "attention": len([c for c in claims if c.verdict != "SUPPORTED" and c.review_status == "pending"]),
                "unsupported": counts["UNSUPPORTED"] + counts["CONTRADICTORY"], "suspicious_refs": len([r for r in refs if r.meta_status != "verified"]),
                "counts": counts, "risk": risk, "integrity": integrity, "activity": activity[:10],
                "recent_reviewed": [doc_dict(d, db) for d in docs if d.status in ("reviewed", "revision_requested")][:5],
                "awaiting_docs": [doc_dict(d, db) for d in docs if d.status in ("submitted", "in_review")][:6]}
    finally:
        db.close()


