# ---- PDF report --------------------------------------------------------------------
def latin(s: Any) -> str:
    s = str(s if s is not None else "")
    for a, b in {"“": '"', "”": '"', "‘": "'", "’": "'", "–": "-", "—": "-", "…": "...", "≥": ">=",
                 "≤": "<=", " ": " ", "•": "-", "→": "->"}.items():
        s = s.replace(a, b)
    return s.encode("latin-1", "replace").decode("latin-1")


VERDICT_RGB = {"SUPPORTED": (22, 163, 74), "PARTIALLY SUPPORTED": (202, 138, 4), "UNSUPPORTED": (220, 38, 38), "CONTRADICTORY": (190, 18, 60),
               "POTENTIALLY OUTDATED": (234, 88, 12), "NEEDS HUMAN REVIEW": (100, 116, 139)}


@app.get("/api/documents/{doc_id}/report.pdf")
def report_pdf(doc_id: int, token: str = "", authorization: str = Header(default="")):
    from fpdf import FPDF
    user = current_user("Bearer " + token if token else authorization)
    db = SessionLocal()
    try:
        d = visible_doc(db, user, doc_id)
        claims = db.query(Claim).filter(Claim.doc_id == d.id).order_by(Claim.idx).all()
        refs = db.query(Reference).filter(Reference.doc_id == d.id).order_by(Reference.idx).all()
        s = doc_summary(db, d)
        owner = db.get(User, d.owner_id)
        pdf = FPDF()
        pdf.set_auto_page_break(True, 15)
        pdf.add_page()
        W = pdf.w - 2 * pdf.l_margin
        pdf.set_fill_color(15, 23, 42)
        pdf.rect(0, 0, pdf.w, 34, "F")
        pdf.set_text_color(255, 255, 255)
        pdf.set_font("Helvetica", "B", 18)
        pdf.set_xy(pdf.l_margin, 9)
        pdf.cell(0, 8, "CiteVerify - Verification Report")
        pdf.set_font("Helvetica", "", 9)
        pdf.set_xy(pdf.l_margin, 19)
        pdf.cell(0, 6, latin("A citation is not proof by itself. Show the evidence behind every claim.   Generated %s UTC" % datetime.utcnow().strftime("%Y-%m-%d %H:%M")))
        pdf.set_text_color(15, 23, 42)
        pdf.set_y(42)
        pdf.set_font("Helvetica", "B", 13)
        pdf.multi_cell(W, 6, latin(d.title))
        pdf.set_font("Helvetica", "", 9)
        pdf.multi_cell(W, 5, latin("Author: %s   |   File: %s (%s)   |   Version %d   |   Status: %s" % (owner.name, d.filename, d.filetype, d.version, d.status)))
        if d.demo:
            pdf.set_text_color(146, 64, 14)
            pdf.multi_cell(W, 5, "Note: this report uses the CiteVerify demo corpus. Its papers are SIMULATED demo data, not real publications.")
            pdf.set_text_color(15, 23, 42)
        pdf.ln(3)
        # stats grid
        stats = [("Claims extracted", s["claims"]), ("References", s["references"]), ("Mapped to sources", s["mapped_refs"]),
                 ("Evidence reliability", "%d%%" % s["reliability"]), ("Suspicious references", s["suspicious_refs"]), ("Risk level", s["risk"].upper())]
        cw = W / 3
        for i, (k, v) in enumerate(stats):
            x = pdf.l_margin + (i % 3) * cw
            y = pdf.get_y() if i % 3 == 0 else y
            pdf.set_fill_color(241, 245, 249)
            pdf.rect(x + 1, y, cw - 2, 16, "F")
            pdf.set_xy(x + 4, y + 2)
            pdf.set_font("Helvetica", "", 8)
            pdf.cell(cw - 8, 4, latin(k))
            pdf.set_xy(x + 4, y + 7)
            pdf.set_font("Helvetica", "B", 13)
            pdf.cell(cw - 8, 7, latin(v))
            if i % 3 == 2:
                pdf.set_y(y + 19)
        pdf.ln(2)
        pdf.set_font("Helvetica", "B", 11)
        pdf.cell(0, 7, "Verdict distribution", new_x="LMARGIN", new_y="NEXT")
        pdf.set_font("Helvetica", "", 9)
        for v in VERDICTS:
            n = s["counts"].get(v, 0)
            pdf.set_fill_color(*VERDICT_RGB[v])
            y = pdf.get_y()
            pdf.rect(pdf.l_margin, y + 1.2, 3, 3, "F")
            pdf.set_x(pdf.l_margin + 5)
            pdf.cell(55, 5.5, latin(v.title()))
            bw = (W - 75) * (n / float(max(1, s["claims"])))
            pdf.rect(pdf.l_margin + 62, y + 1.2, max(bw, 0.5), 3, "F")
            pdf.set_x(pdf.l_margin + 62 + (W - 75) + 2)
            pdf.cell(10, 5.5, str(n), new_x="LMARGIN", new_y="NEXT")
        pdf.ln(3)

        def section(title):
            pdf.ln(2)
            pdf.set_font("Helvetica", "B", 12)
            pdf.set_text_color(15, 23, 42)
            pdf.cell(0, 8, latin(title), new_x="LMARGIN", new_y="NEXT")
            pdf.set_draw_color(203, 213, 225)
            pdf.line(pdf.l_margin, pdf.get_y(), pdf.l_margin + W, pdf.get_y())
            pdf.ln(2)

        section("Claim-by-claim verification")
        for c in claims:
            p = db.get(Paper, c.paper_id) if c.paper_id else None
            if pdf.get_y() > 245:
                pdf.add_page()
            pdf.set_font("Helvetica", "B", 9)
            pdf.set_text_color(*VERDICT_RGB.get(c.verdict, (0, 0, 0)))
            pdf.cell(0, 5, latin("Claim %d  -  %s  -  confidence %d%%" % (c.idx, c.verdict, round(c.confidence * 100))), new_x="LMARGIN", new_y="NEXT")
            pdf.set_text_color(15, 23, 42)
            pdf.set_font("Helvetica", "", 9)
            pdf.multi_cell(W, 4.6, latin('"%s"' % c.text))
            pdf.set_font("Helvetica", "I", 8.5)
            pdf.set_text_color(71, 85, 105)
            if p:
                pdf.multi_cell(W, 4.4, latin("Source: %s (%s)%s%s" % (p.title, p.year or "n.d.", "  doi:" + p.doi if p.doi else "", "  [simulated demo paper]" if p.simulated else "")))
            for e in jl(c.evidence, [])[:2]:
                loc = ", ".join(x for x in [e.get("section") or "", ("p. %s" % e["page"]) if e.get("page") else ""] if x)
                pdf.multi_cell(W, 4.4, latin("Evidence [%s%s]: \"%s\"" % (e.get("label", ""), (", " + loc) if loc else "", e["text"])))
            pdf.set_font("Helvetica", "", 8.5)
            pdf.set_text_color(15, 23, 42)
            pdf.multi_cell(W, 4.4, latin("Reason: " + c.explanation))
            if c.prof_note:
                pdf.multi_cell(W, 4.4, latin("Evaluator note: " + c.prof_note))
            pdf.ln(2.5)
        outd = [c for c in claims if jl(c.outdated, {})]
        section("Outdated research alerts")
        pdf.set_font("Helvetica", "", 9)
        if not outd:
            pdf.multi_cell(W, 5, "No outdated-evidence alerts.")
        for c in outd:
            o = jl(c.outdated, {})
            pdf.multi_cell(W, 4.6, latin("Claim %d: source from %s (%s years old). %s" % (c.idx, o.get("year"), o.get("age"), o.get("note"))))
            for n in o.get("newer", []):
                pdf.multi_cell(W, 4.6, latin("   Newer: %s (%s) - \"%s\"" % (n["title"], n["year"], n["finding"])))
        section("Suspicious references")
        sus = [r for r in refs if r.meta_status != "verified"]
        if not sus:
            pdf.multi_cell(W, 5, "All references matched their publication records.")
        for r in sus:
            pdf.set_font("Helvetica", "B", 9)
            pdf.multi_cell(W, 4.6, latin("[%s] %s" % (r.label, "CONFIRMED METADATA MISMATCH" if r.meta_status == "mismatch" else "COULD NOT BE VERIFIED")))
            pdf.set_font("Helvetica", "", 8.5)
            pdf.multi_cell(W, 4.4, latin(r.raw))
            for i in jl(r.issues, []):
                pdf.multi_cell(W, 4.4, latin("   - " + i["message"]))
        section("Items requiring human review")
        hr = [c for c in claims if c.verdict in ("NEEDS HUMAN REVIEW", "CONTRADICTORY", "UNSUPPORTED")]
        pdf.set_font("Helvetica", "", 9)
        for c in hr:
            pdf.multi_cell(W, 4.6, latin("- Claim %d (%s): %s" % (c.idx, c.verdict.title(), c.text)))
        if not hr:
            pdf.multi_cell(W, 5, "None.")
        pdf.ln(4)
        pdf.set_font("Helvetica", "I", 7.5)
        pdf.set_text_color(100, 116, 139)
        pdf.multi_cell(W, 4, "Confidence reflects the strength of the available evidence, not a guarantee of correctness. Verdicts based only on "
                             "abstracts are weaker than full-text verification. Always confirm high-stakes findings manually.")
        data = bytes(pdf.output())
        fname = re.sub(r"[^A-Za-z0-9]+", "-", d.title)[:60].strip("-") + "-citeverify-report.pdf"
        return Response(data, media_type="application/pdf", headers={"Content-Disposition": 'attachment; filename="%s"' % fname})
    finally:
        db.close()


