def seed_progress_history():
    """Idempotent: adds earlier, already-reviewed submissions (and feedback on them) for the demo students."""
    db = SessionLocal()
    try:
        prof = db.query(User).filter(User.role == "professor").first()
        if not prof or db.query(Document).filter(Document.filename.like("history-%")).first():
            return
        now = datetime.utcnow()
        for key, chain, versions in PROGRESS_HISTORY:
            u = db.query(User).filter(User.email == "%s@citeverify.demo" % key).first()
            current = u and db.query(Document).filter(Document.owner_id == u.id, Document.status.in_(REVIEW_STATES)).order_by(Document.submitted_at).first()
            if not current:
                continue
            title = current.title if chain else "Wearables and Predictive Analytics: Literature Note"
            prev = None
            for n, (items, days, sent, addressed) in enumerate(versions):
                spec = {"title": title, "abstract": "Earlier draft submitted for review.", "items": items}
                text = build_document_text(spec)
                d = Document(owner_id=u.id, title=title, filename="history-%s-v%d.docx" % (key, n + 1), filetype="DOCX", size=len(text.encode()),
                             text=text, version=n + 1, prev_id=prev.id if prev else None, root_id=prev.root_id if prev else None,
                             status="processing", demo=True, created_at=now - timedelta(days=days, hours=3))
                db.add(d)
                db.commit()
                if not prev:
                    d.root_id = d.id
                    db.commit()
                analyze_document(d.id, live=False, pause=0)
                d = db.get(Document, d.id)
                d.status, d.submitted_at, d.reviewed_at = "revision_requested", now - timedelta(days=days), now - timedelta(days=days - 1)
                db.commit()
                bad = [c for c in db.query(Claim).filter(Claim.doc_id == d.id).order_by(Claim.idx).all() if c.verdict != "SUPPORTED"]
                for i, c in enumerate(bad[:sent]):
                    db.add(Feedback(doc_id=d.id, student_id=u.id, professor_id=prof.id, claim_id=c.id, body=template_feedback(c, db),
                                    status="addressed" if i < addressed else "sent", created_at=d.reviewed_at, sent_at=d.reviewed_at,
                                    addressed_at=d.reviewed_at + timedelta(days=2) if i < addressed else None))
                db.commit()
                prev = d
            if chain:  # the existing submission becomes the latest version of this chain
                current.prev_id, current.root_id, current.version = prev.id, prev.root_id, prev.version + 1
                for f_ in db.query(Document).filter(Document.root_id == current.id, Document.id != current.id).all():
                    f_.root_id = prev.root_id
                db.commit()
        # Kabir has not acted on the feedback for his latest submission either.
        k = db.query(User).filter(User.email == "kabir@citeverify.demo").first()
        kd = k and db.query(Document).filter(Document.owner_id == k.id, Document.filename.notlike("history-%")).first()
        if kd:
            for c in db.query(Claim).filter(Claim.doc_id == kd.id, Claim.verdict != "SUPPORTED").all():
                db.add(Feedback(doc_id=kd.id, student_id=k.id, professor_id=prof.id, claim_id=c.id, body=template_feedback(c, db),
                                status="sent", created_at=now - timedelta(days=4), sent_at=now - timedelta(days=4)))
            db.commit()
        print("[seed] added earlier submissions for student progress")
    finally:
        db.close()


seed_progress_history()


# ---------------------------------------------------------------------------
# Website (single-file deploy)
# The whole frontend (code, styles, login illustrations) is embedded at the very end of this file as gzip+base64
# (WEBSITE_GZ_B64), written there by `npm run build` in frontend/. The backend folder therefore needs no static files.
# ---------------------------------------------------------------------------
_site_cache: Dict[str, Any] = {}


def website() -> Dict[str, Any]:
    # A rebuild rewrites the last line of this file; re-read it then, so a running server serves the new site at once.
    try:
        mtime = os.path.getmtime(__file__)
    except OSError:
        mtime = None
    if not _site_cache or (mtime and mtime != _site_cache.get("mtime")):
        b64 = globals().get("WEBSITE_GZ_B64", "")
        if _site_cache:  # file changed since start-up: take the embedded site from its last line
            with open(__file__, "rb") as fh:
                fh.seek(max(0, os.path.getsize(__file__) - 4 * 1024 * 1024))
                last = fh.read().decode("utf-8", "ignore").rstrip().rsplit("\n", 1)[-1]
            if last.startswith("WEBSITE_GZ_B64 = "):
                b64 = json.loads(last[len("WEBSITE_GZ_B64 = "):])
        gz = base64.b64decode(b64)
        if gz:
            import gzip
            _site_cache.update(gz=gz, raw=gzip.decompress(gz), etag='"%s"' % hashlib.sha256(gz).hexdigest()[:20], mtime=mtime)
    return _site_cache


@app.get("/{full_path:path}")
def spa(full_path: str, if_none_match: str = Header(default=""), accept_encoding: str = Header(default="")):
    if full_path.startswith("api/"):
        raise HTTPException(404, "Not found")
    site = website()
    if not site:
        return Response("Website not built yet: run `npm run build` in frontend/.", status_code=503, media_type="text/plain")
    # Browsers re-check on every load ("no-cache"); an unchanged build gets a cheap 304, a new build is picked up at once.
    headers = {"Cache-Control": "no-cache", "ETag": site["etag"], "Vary": "Accept-Encoding"}
    if site["etag"] in [t.strip() for t in if_none_match.split(",")]:
        return Response(status_code=304, headers=headers)
    if "gzip" in accept_encoding.lower():  # send the stored compressed bytes as-is (no per-request compression)
        return Response(site["gz"], media_type="text/html; charset=utf-8", headers=dict(headers, **{"Content-Encoding": "gzip"}))
    return Response(site["raw"], media_type="text/html; charset=utf-8", headers=headers)


# ---------------------------------------------------------------------------
# Embedded website - GENERATED by `npm run build` in frontend/. Do not edit by hand; keep this as the last line.
# ---------------------------------------------------------------------------
WEBSITE_GZ_B64 = ""
